describe('Authentication - Incorrect Password Error', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
  });

  it('should display error message when entering incorrect password', () => {
    // Arrange
    const validEmail = 'user@example.com';
    const incorrectPassword = 'wrongpassword123';
    const expectedErrorMessage = 'Invalid email or password';

    // Act
    cy.get('[data-testid="email-input"]')
      .type(validEmail)
      .should('have.value', validEmail);

    cy.get('[data-testid="password-input"]')
      .type(incorrectPassword)
      .should('have.value', incorrectPassword);

    cy.get('[data-testid="login-button"]').click();

    // Assert
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', expectedErrorMessage);

    cy.get('[data-testid="error-message"]')
      .should('have.css', 'color')
      .and('include', 'rgb(220, 53, 69)');

    // Verify user remains on login page
    cy.url().should('include', '/login');
  });

  it('should display error message on multiple incorrect password attempts', () => {
    const validEmail = 'testuser@example.com';
    const incorrectPasswords = ['wrong1', 'wrong2', 'wrong3'];

    incorrectPasswords.forEach((password) => {
      cy.get('[data-testid="email-input"]').clear().type(validEmail);
      cy.get('[data-testid="password-input"]').clear().type(password);
      cy.get('[data-testid="login-button"]').click();

      cy.get('[data-testid="error-message"]')
        .should('be.visible')
        .and('contain', 'Invalid email or password');
    });
  });

  it('should clear error message when user modifies password field', () => {
    const validEmail = 'user@example.com';
    const incorrectPassword = 'wrongpassword';

    cy.get('[data-testid="email-input"]').type(validEmail);
    cy.get('[data-testid="password-input"]').type(incorrectPassword);
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="error-message"]').should('be.visible');

    // Act - modify password field
    cy.get('[data-testid="password-input"]').type('123');

    // Assert - error message should be cleared
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});

