import { test, expect, Page } from '@playwright/test';

test.describe('Authentication - Incorrect Password Error', () => {
  let page: Page;

  test.beforeEach(async ({ page: testPage }) => {
    page = testPage;
    await page.goto('/login');
    await expect(page.locator('[data-testid="login-form"]')).toBeVisible();
  });

  test('should display error message when entering incorrect password', async () => {
    // Arrange
    const validEmail = 'user@example.com';
    const incorrectPassword = 'wrongpassword123';
    const expectedErrorMessage = 'Invalid email or password';

    // Act
    await page.locator('[data-testid="email-input"]').fill(validEmail);
    await expect(page.locator('[data-testid="email-input"]')).toHaveValue(validEmail);

    await page.locator('[data-testid="password-input"]').fill(incorrectPassword);
    await expect(page.locator('[data-testid="password-input"]')).toHaveValue(incorrectPassword);

    await page.locator('[data-testid="login-button"]').click();

    // Assert
    const errorMessage = page.locator('[data-testid="error-message"]');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText(expectedErrorMessage);

    const computedStyle = await errorMessage.evaluate(
      (el) => window.getComputedStyle(el).color
    );
    expect(computedStyle).toMatch(/rgb\(220,\s*53,\s*69\)|#dc3545/);

    // Verify user remains on login page
    await expect(page).toHaveURL(/\/login/);
  });

  test('should display error message on multiple incorrect password attempts', async () => {
    // Arrange
    const validEmail = 'testuser@example.com';
    const incorrectPasswords = ['wrong1', 'wrong2', 'wrong3'];

    // Act & Assert
    for (const password of incorrectPasswords) {
      await page.locator('[data-testid="email-input"]').fill(validEmail);
      await page.locator('[data-testid="password-input"]').fill(password);
      await page.locator('[data-testid="login-button"]').click();

      const errorMessage = page.locator('[data-testid="error-message"]');
      await expect(errorMessage).toBeVisible();
      await expect(errorMessage).toContainText('Invalid email or password');

      // Wait before next attempt
      await page.waitForTimeout(500);
    }
  });

  test('should clear error message when user modifies password field', async () => {
    // Arrange
    const validEmail = 'user@example.com';
    const incorrectPassword = 'wrongpassword';

    // Act - trigger error
    await page.locator('[data-testid="email-input"]').fill(validEmail);
    await page.locator('[data-testid="password-input"]').fill(incorrectPassword);
    await page.locator('[data-testid="login-button"]').click();

    // Assert - error is visible
    await expect(page.locator('[data-testid="error-message"]')).toBeVisible();

    // Act - modify password
    await page.locator('[data-testid="password-input"]').fill(incorrectPassword + '123');

    // Assert - error should be cleared
    await expect(page.locator('[data-testid="error-message"]')).not.toBeVisible();
  });
});

