describe('Secure Logout - Cypress', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePass123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="dashboard-heading"]').should('be.visible');
  });

  it('should successfully log out and redirect to login page', () => {
    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="logout-button"]').click();
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-heading"]').should('be.visible');
  });

  it('should terminate session and invalidate auth token', () => {
    cy.intercept('POST', '/api/auth/logout', {
      statusCode: 200,
      body: { message: 'Logged out successfully' }
    }).as('logoutRequest');

    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="logout-button"]').click();
    cy.wait('@logoutRequest');

    cy.request({
      method: 'GET',
      url: '/api/user/profile',
      failOnStatusCode: false
    }).then((response) => {
      expect(response.status).to.equal(401);
    });
  });

  it('should clear session storage and local storage on logout', () => {
    cy.window().then((win) => {
      win.localStorage.setItem('authToken', 'test-token-123');
      win.sessionStorage.setItem('sessionId', 'session-456');
    });

    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="logout-button"]').click();

    cy.window().then((win) => {
      expect(win.localStorage.getItem('authToken')).to.be.null;
      expect(win.sessionStorage.getItem('sessionId')).to.be.null;
    });
  });

  it('should prevent access to protected pages after logout', () => {
    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="logout-button"]').click();
    cy.url().should('include', '/login');

    cy.visit('/dashboard', { failOnStatusCode: false });
    cy.url().should('include', '/login');
  });

  it('should display success message on logout', () => {
    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="logout-button"]').click();
    cy.get('[data-testid="logout-success-toast"]').should('be.visible');
    cy.get('[data-testid="logout-success-toast"]').should('contain', 'Successfully logged out');
  });
});

