import { test, expect } from '@playwright/test';

test.describe('Secure Logout - Playwright', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
    await page.fill('[data-testid="email-input"]', 'user@example.com');
    await page.fill('[data-testid="password-input"]', 'SecurePass123');
    await page.click('[data-testid="login-button"]');
    await page.waitForSelector('[data-testid="dashboard-heading"]');
  });

  test('should successfully log out and redirect to login page', async ({ page }) => {
    await page.click('[data-testid="user-menu-button"]');
    await page.click('[data-testid="logout-button"]');
    await expect(page).toHaveURL(/\/login/);
    await expect(page.locator('[data-testid="login-heading"]')).toBeVisible();
  });

  test('should terminate session and invalidate auth token', async ({ page }) => {
    await page.route('**/api/auth/logout', (route) => {
      route.abort('failed');
    });

    await page.click('[data-testid="user-menu-button"]');
    await page.click('[data-testid="logout-button"]');
    await page.waitForURL(/\/login/);

    const response = await page.request.get('/api/user/profile');
    expect(response.status()).toBe(401);
  });

  test('should clear session storage and local storage on logout', async ({ page }) => {
    await page.evaluate(() => {
      localStorage.setItem('authToken', 'test-token-123');
      sessionStorage.setItem('sessionId', 'session-456');
    });

    await page.click('[data-testid="user-menu-button"]');
    await page.click('[data-testid="logout-button"]');

    const authToken = await page.evaluate(() => localStorage.getItem('authToken'));
    const sessionId = await page.evaluate(() => sessionStorage.getItem('sessionId'));

    expect(authToken).toBeNull();
    expect(sessionId).toBeNull();
  });

  test('should prevent access to protected pages after logout', async ({ page }) => {
    await page.click('[data-testid="user-menu-button"]');
    await page.click('[data-testid="logout-button"]');
    await expect(page).toHaveURL(/\/login/);

    const response = await page.goto('/dashboard');
    expect(response?.status()).not.toBe(200);
    await expect(page).toHaveURL(/\/login/);
  });

  test('should display success message on logout', async ({ page }) => {
    await page.click('[data-testid="user-menu-button"]');
    await page.click('[data-testid="logout-button"]');

    const successToast = page.locator('[data-testid="logout-success-toast"]');
    await expect(successToast).toBeVisible();
    await expect(successToast).toContainText('Successfully logged out');
  });
});

