describe('Authentication - Protected Page Redirect', () => {
  beforeEach(() => {
    cy.clearLocalStorage();
    cy.clearCookies();
  });

  it('should redirect unauthenticated user to login when accessing protected page', () => {
    cy.visit('/dashboard', { failOnStatusCode: false });
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-heading"]').should('be.visible');
  });

  it('should redirect to login when accessing protected resource without token', () => {
    cy.visit('/profile', { failOnStatusCode: false });
    cy.url().should('match', /\/login/);
    cy.get('[data-testid="login-form"]').should('exist');
  });

  it('should redirect to login when accessing admin page unauthenticated', () => {
    cy.visit('/admin/users', { failOnStatusCode: false });
    cy.url().should('include', '/login');
    cy.contains('Please log in to continue').should('be.visible');
  });

  it('should allow access to protected page with valid authentication token', () => {
    cy.login('user@example.com', 'password123');
    cy.visit('/dashboard');
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-content"]').should('be.visible');
  });

  it('should redirect to login after token expiration', () => {
    cy.login('user@example.com', 'password123');
    cy.visit('/dashboard');
    cy.get('[data-testid="dashboard-content"]').should('be.visible');
    cy.clearLocalStorage('authToken');
    cy.visit('/dashboard', { failOnStatusCode: false });
    cy.url().should('include', '/login');
  });

  it('should preserve redirect path after successful login', () => {
    cy.visit('/dashboard', { failOnStatusCode: false });
    cy.url().should('include', '/login');
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-submit"]').click();
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-content"]').should('be.visible');
  });
});

Cypress.Commands.add('login', (email, password) => {
  cy.visit('/login');
  cy.get('[data-testid="email-input"]').type(email);
  cy.get('[data-testid="password-input"]').type(password);
  cy.get('[data-testid="login-submit"]').click();
  cy.url().should('not.include', '/login');
});

