import { test, expect } from '@playwright/test';

test.describe('Authentication - Protected Page Redirect', () => {
  test.beforeEach(async ({ context }) => {
    await context.clearCookies();
    const localStorageState = { cookies: [] };
  });

  test('should redirect unauthenticated user to login when accessing protected page', async ({ page }) => {
    await page.goto('/dashboard', { waitUntil: 'networkidle' });
    expect(page.url()).toContain('/login');
    await expect(page.getByTestId('login-heading')).toBeVisible();
  });

  test('should redirect to login when accessing protected resource without token', async ({ page }) => {
    await page.goto('/profile', { waitUntil: 'networkidle' });
    expect(page.url()).toMatch(/\/login/);
    await expect(page.getByTestId('login-form')).toBeVisible();
  });

  test('should redirect to login when accessing admin page unauthenticated', async ({ page }) => {
    await page.goto('/admin/users', { waitUntil: 'networkidle' });
    expect(page.url()).toContain('/login');
    await expect(page.getByText('Please log in to continue')).toBeVisible();
  });

  test('should allow access to protected page with valid authentication token', async ({ page, context }) => {
    await login(page, 'user@example.com', 'password123');
    await page.goto('/dashboard');
    expect(page.url()).toContain('/dashboard');
    await expect(page.getByTestId('dashboard-content')).toBeVisible();
  });

  test('should redirect to login after token expiration', async ({ page, context }) => {
    await login(page, 'user@example.com', 'password123');
    await page.goto('/dashboard');
    await expect(page.getByTestId('dashboard-content')).toBeVisible();

    await context.clearCookies();
    await page.evaluate(() => localStorage.removeItem('authToken'));

    await page.goto('/dashboard', { waitUntil: 'networkidle' });
    expect(page.url()).toContain('/login');
  });

  test('should preserve redirect path after successful login', async ({ page }) => {
    await page.goto('/dashboard', { waitUntil: 'networkidle' });
    expect(page.url()).toContain('/login');

    await page.getByTestId('email-input').fill('user@example.com');
    await page.getByTestId('password-input').fill('password123');
    await page.getByTestId('login-submit').click();

    await page.waitForURL('**/dashboard');
    await expect(page.getByTestId('dashboard-content')).toBeVisible();
  });
});

async function login(page, email, password) {
  await page.goto('/login');
  await page.getByTestId('email-input').fill(email);
  await page.getByTestId('password-input').fill(password);
  await page.getByTestId('login-submit').click();
  await page.waitForURL(url => !url.pathname.includes('/login'));
}

