describe('Password Reset Confirmation Message', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display confirmation message after successful password reset', () => {
    // Navigate to password reset
    cy.contains('a', 'Forgot password').click();
    cy.url().should('include', '/forgot-password');

    // Enter email address
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="reset-password-btn"]').click();

    // Verify success confirmation message appears
    cy.get('[data-testid="confirmation-message"]')
      .should('be.visible')
      .and('contain', 'Password reset link has been sent to your email');

    // Verify message has correct styling/attributes
    cy.get('[data-testid="confirmation-message"]')
      .should('have.class', 'success')
      .and('have.attr', 'role', 'alert');
  });

  it('should display confirmation message with complete reset flow', () => {
    cy.contains('a', 'Forgot password').click();
    cy.get('[data-testid="email-input"]').type('testuser@example.com');

    // Intercept the password reset request
    cy.intercept('POST', '/api/auth/forgot-password', {
      statusCode: 200,
      body: { success: true, message: 'Reset link sent' }
    }).as('resetRequest');

    cy.get('[data-testid="reset-password-btn"]').click();
    cy.wait('@resetRequest');

    // Verify confirmation message is displayed
    cy.get('[data-testid="confirmation-message"]')
      .should('exist')
      .and('be.visible')
      .and('contain', 'Password reset link has been sent');

    // Verify message can be dismissed
    cy.get('[data-testid="close-message-btn"]').click();
    cy.get('[data-testid="confirmation-message"]').should('not.be.visible');
  });

  it('should keep confirmation message visible for adequate time', () => {
    cy.contains('a', 'Forgot password').click();
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="reset-password-btn"]').click();

    // Message should be visible immediately
    cy.get('[data-testid="confirmation-message"]').should('be.visible');

    // Wait 2 seconds and verify still visible
    cy.wait(2000);
    cy.get('[data-testid="confirmation-message"]').should('be.visible');
  });
});

