describe('Phone Number Field - Numeric Input Validation', () => {
  beforeEach(() => {
    cy.visit('/contact-form');
    cy.get('[data-testid="phone-input"]').as('phoneField');
  });

  it('should accept numeric input in phone number field', () => {
    cy.get('@phoneField')
      .type('5551234567')
      .should('have.value', '5551234567');
  });

  it('should reject alphabetic characters', () => {
    cy.get('@phoneField')
      .type('555ABC1234')
      .should('have.value', '5551234');
  });

  it('should reject special characters except allowed delimiters', () => {
    cy.get('@phoneField')
      .type('555!@#1234')
      .should('have.value', '5551234');
  });

  it('should accept hyphen and space delimiters', () => {
    cy.get('@phoneField')
      .type('555-123-4567')
      .should('have.value', '555-123-4567');
  });

  it('should accept parentheses for area code format', () => {
    cy.get('@phoneField')
      .type('(555)123-4567')
      .should('have.value', '(555)123-4567');
  });

  it('should reject mixed alphanumeric input', () => {
    cy.get('@phoneField')
      .type('Phone555Test1234')
      .should('have.value', '5551234');
  });

  it('should handle paste event with non-numeric characters', () => {
    const invalidInput = '555-ABC-1234';
    cy.get('@phoneField')
      .invoke('val', invalidInput)
      .trigger('input')
      .should('have.value', '555-1234');
  });

  it('should allow leading plus sign for international format', () => {
    cy.get('@phoneField')
      .type('+15551234567')
      .should('have.value', '+15551234567');
  });

  it('should clear field and accept new numeric input', () => {
    cy.get('@phoneField')
      .type('5551234567')
      .clear()
      .type('9876543210')
      .should('have.value', '9876543210');
  });

  it('should validate phone field on form submission', () => {
    cy.get('@phoneField').type('555123');
    cy.get('[data-testid="submit-btn"]').click();
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Please enter a valid phone number');
  });
});

