import { test, expect } from '@playwright/test';

test.describe('Phone Number Field - Numeric Input Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/contact-form');
  });

  test('should accept numeric input in phone number field', async ({ page }) => {
    const phoneInput = page.locator('[data-testid="phone-input"]');
    await phoneInput.fill('5551234567');
    await expect(phoneInput).toHaveValue('5551234567');
  });

  test('should reject alphabetic characters', async ({ page }) => {
    const phoneInput = page.locator('[data-testid="phone-input"]');
    await phoneInput.type('555ABC1234', { delay: 50 });
    const value = await phoneInput.inputValue();
    expect(value).toMatch(/^[0-9\-\s()]*$/);
    expect(value).not.toContain('A');
    expect(value).not.toContain('B');
    expect(value).not.toContain('C');
  });

  test('should reject special characters except allowed delimiters', async ({ page }) => {
    const phoneInput = page.locator('[data-testid="phone-input"]');
    await phoneInput.type('555!@#1234', { delay: 50 });
    const value = await phoneInput.inputValue();
    expect(value).not.toContain('!');
    expect(value).not.toContain('@');
    expect(value).not.toContain('#');
  });

  test('should accept hyphen and space delimiters', async ({ page }) => {
    const phoneInput = page.locator('[data-testid="phone-input"]');
    await phoneInput.fill('555-123-4567');
    await expect(phoneInput).toHaveValue('555-123-4567');
  });

  test('should accept parentheses for area code format', async ({ page }) => {
    const phoneInput = page.locator('[data-testid="phone-input"]');
    await phoneInput.fill('(555)123-4567');
    await expect(phoneInput).toHaveValue('(555)123-4567');
  });

  test('should reject mixed alphanumeric input', async ({ page }) => {
    const phoneInput = page.locator('[data-testid="phone-input"]');
    await phoneInput.type('Phone555Test1234', { delay: 50 });
    const value = await phoneInput.inputValue();
    expect(value).toMatch(/^[0-9\-\s()+]*$/);
  });

  test('should handle paste event with non-numeric characters', async ({ page }) => {
    const phoneInput = page.locator('[data-testid="phone-input"]');
    await phoneInput.evaluate((el) => {
      (el as HTMLInputElement).value = '555-ABC-1234';
      el.dispatchEvent(new Event('input', { bubbles: true }));
    });
    const value = await phoneInput.inputValue();
    expect(value).not.toContain('A');
    expect(value).not.toContain('B');
    expect(value).not.toContain('C');
  });

  test('should allow leading plus sign for international format', async ({ page }) => {
    const phoneInput = page.locator('[data-testid="phone-input"]');
    await phoneInput.fill('+15551234567');
    await expect(phoneInput).toHaveValue('+15551234567');
  });

  test('should clear field and accept new numeric input', async ({ page }) => {
    const phoneInput = page.locator('[data-testid="phone-input"]');
    await phoneInput.fill('5551234567');
    await phoneInput.clear();
    await phoneInput.fill('9876543210');
    await expect(phoneInput).toHaveValue('9876543210');
  });

  test('should validate phone field on form submission', async ({ page }) => {
    const phoneInput = page.locator('[data-testid="phone-input"]');
    const submitBtn = page.locator('[data-testid="submit-btn"]');
    const errorMessage = page.locator('[data-testid="error-message"]');

    await phoneInput.fill('555123');
    await submitBtn.click();

    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Please enter a valid phone number');
  });
});

