    await aboutNavItem.click();
    await expect(page).toHaveURL(/\/about/);

    await expect(aboutNavItem).toHaveClass(/active/);
    await expect(homeNavItem).not.toHaveClass(/active/);
  });

  test('should highlight active menu item for products page', async () => {
    const productsNavItem = page.locator('[data-testid="nav-products"]');
    const activeIndicator = productsNavItem.locator('[data-testid="active-indicator"]');

    await productsNavItem.click();
    await expect(page).toHaveURL(/\/products/);

    await expect(productsNavItem).toHaveClass(/active/);
    await expect(activeIndicator).toBeVisible();
  });

  test('should maintain active state after page refresh', async () => {
    const contactNavItem = page.locator('[data-testid="nav-contact"]');

    await contactNavItem.click();
    await expect(page).toHaveURL(/\/contact/);

    await page.reload();

    await expect(contactNavItem).toHaveClass(/active/);
  });

  test('should remove active class from previous item when navigating', async () => {
    const homeNavItem = page.locator('[data-testid="nav-home"]');
    const servicesNavItem = page.locator('[data-testid="nav-services"]');

    await expect(homeNavItem).toHaveClass(/active/);

    await servicesNavItem.click();

    await expect(homeNavItem).not.toHaveClass(/active/);
    await expect(servicesNavItem).toHaveClass(/active/);
  });

  test('should highlight active menu item with distinct visual styling', async () => {
    const aboutNavItem = page.locator('[data-testid="nav-about"]');
    const homeNavItem = page.locator('[data-testid="nav-home"]');

    await aboutNavItem.click();

    const activeBgColor = await aboutNavItem.evaluate(
      (el) => window.getComputedStyle(el).backgroundColor
    );
    const inactiveBgColor = await homeNavItem.evaluate(
      (el) => window.getComputedStyle(el).backgroundColor
    );

    expect(activeBgColor).not.toBe('rgba(0, 0, 0, 0)');
    expect(inactiveBgColor).toBe('rgba(0, 0, 0, 0)');
  });
});

