describe('404 Page Navigation', () => {
  beforeEach(() => {
    cy.visit('/', { failOnStatusCode: false });
  });

  it('should display 404 page for invalid URL path', () => {
    cy.visit('/invalid-page-that-does-not-exist', { failOnStatusCode: false });
    cy.contains('404').should('be.visible');
    cy.contains(/page not found|not found/i).should('be.visible');
  });

  it('should display 404 page for deeply nested invalid path', () => {
    cy.visit('/some/deeply/nested/invalid/path', { failOnStatusCode: false });
    cy.get('[data-testid="error-page"]').should('exist');
    cy.contains('404').should('be.visible');
  });

  it('should contain link to home page on 404', () => {
    cy.visit('/nonexistent', { failOnStatusCode: false });
    cy.get('a[href="/"], a[data-testid="home-link"]').should('exist');
  });

  it('should return 404 status code for invalid URL', () => {
    cy.request({ url: '/invalid-url', failOnStatusCode: false }).then((response) => {
      expect(response.status).to.equal(404);
    });
  });

  it('should display 404 error when navigating to invalid route via link', () => {
    cy.visit('/dashboard');
    cy.intercept('GET', '/invalid-route', {
      statusCode: 404,
      body: { error: 'Not Found' }
    });
    cy.get('a[href="/invalid-route"]').click({ force: true });
    cy.contains('404').should('be.visible');
  });

  it('should have proper heading on 404 page', () => {
    cy.visit('/not-a-real-page', { failOnStatusCode: false });
    cy.get('h1, h2').contains(/404|not found/i).should('be.visible');
  });

  it('should maintain navigation on 404 page', () => {
    cy.visit('/invalid', { failOnStatusCode: false });
    cy.get('[data-testid="navbar"], nav').should('be.visible');
  });
});

