    expect(relAttr).toContain('noopener');
  });

  test('should not open internal links in new tab', async ({ page }) => {
    const internalLink = page.locator('a[href^="/"]').first();
    const targetAttr = await internalLink.getAttribute('target');
    expect(targetAttr).not.toBe('_blank');
  });

  test('should handle external link navigation attributes', async ({ page }) => {
    const externalLink = page.getByTestId('external-link');
    await expect(externalLink).toHaveAttribute('target', '_blank');
    const href = await externalLink.getAttribute('href');
    expect(href).toContain('http');
  });

  test('should verify all external links have correct attributes', async ({ page }) => {
    const externalLinks = page.locator('a[href*="http"]');
    const count = await externalLinks.count();

    for (let i = 0; i < count; i++) {
      const link = externalLinks.nth(i);
      await expect(link).toHaveAttribute('target', '_blank');
      const relAttr = await link.getAttribute('rel');
      expect(relAttr).toContain('noopener');
    }
  });

  test('should include noreferrer for privacy protection', async ({ page }) => {
    const externalLink = page.getByTestId('external-link');
    const relAttr = await externalLink.getAttribute('rel');
    expect(relAttr).toContain('noreferrer');
  });

  test('should differentiate between internal and external navigation', async ({ page }) => {
    const navLinks = page.locator('nav a');
    const count = await navLinks.count();

    for (let i = 0; i < count; i++) {
      const link = navLinks.nth(i);
      const href = await link.getAttribute('href');

      if (href && href.startsWith('http')) {
        await expect(link).toHaveAttribute('target', '_blank');
      } else {
        const targetAttr = await link.getAttribute('target');
        expect(targetAttr).not.toBe('_blank');
      }
    }
  });

  test('should not trigger navigation when verifying link attributes', async ({ page, context }) => {
    const newPagePromise = context.waitForEvent('page');
    const externalLink = page.getByTestId('external-link');

    await expect(externalLink).toHaveAttribute('target', '_blank');
    const targetAttr = await externalLink.getAttribute('target');
    expect(targetAttr).toBe('_blank');
  });
});

