describe('Account Lock After Failed Login Attempts', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/login');
  });

  it('Should lock account after 5 failed login attempts', () => {
    const invalidPassword = 'wrongpassword';
    const validUsername = 'testuser@example.com';

    // Attempt 1
    cy.get('input[name="username"]').type(validUsername);
    cy.get('input[name="password"]').type(invalidPassword);
    cy.get('button[type="submit"]').click();
    cy.contains('Invalid credentials').should('be.visible');

    // Attempt 2
    cy.get('input[name="password"]').clear().type(invalidPassword);
    cy.get('button[type="submit"]').click();
    cy.contains('Invalid credentials').should('be.visible');

    // Attempt 3
    cy.get('input[name="password"]').clear().type(invalidPassword);
    cy.get('button[type="submit"]').click();
    cy.contains('Invalid credentials').should('be.visible');

    // Attempt 4
    cy.get('input[name="password"]').clear().type(invalidPassword);
    cy.get('button[type="submit"]').click();
    cy.contains('Invalid credentials').should('be.visible');

    // Attempt 5 - Account should be locked
    cy.get('input[name="password"]').clear().type(invalidPassword);
    cy.get('button[type="submit"]').click();
    cy.contains('Account locked due to multiple failed login attempts').should('be.visible');
    cy.get('button[type="submit"]').should('be.disabled');
  });

  it('Should display lock message and prevent further login attempts', () => {
    const validUsername = 'lockeduser@example.com';
    const correctPassword = 'correctpassword';

    cy.get('input[name="username"]').type(validUsername);
    cy.get('input[name="password"]').type(correctPassword);
    cy.get('button[type="submit"]').click();
    cy.contains('Account is locked').should('be.visible');
    cy.get('button[type="submit"]').should('be.disabled');
  });

  it('Should allow admin to unlock account', () => {
    cy.visit('http://localhost:3000/admin/users');
    cy.get('input[type="search"]').type('lockeduser@example.com');
    cy.get('table tbody tr').first().within(() => {
      cy.get('button[aria-label="unlock account"]').click();
    });
    cy.contains('Account unlocked successfully').should('be.visible');
  });

  it('Should reset failed login counter after successful login', () => {
    const validUsername = 'testuser@example.com';
    const correctPassword = 'correctpassword';

    cy.get('input[name="username"]').type(validUsername);
    cy.get('input[name="password"]').type(correctPassword);
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');
    cy.visit('http://localhost:3000/logout');
    cy.visit('http://localhost:3000/login');
    cy.get('button[type="submit"]').should('not.be.disabled');
  });
});

