      win.localStorage.setItem('authToken', 'mock_token');
    });
    cy.visit('http://localhost:3000/dashboard');
    cy.get('[data-testid="user-profile"]').should('be.visible');
  });

  it('should display user email after successful login', () => {
    cy.intercept('POST', '**/auth/google/callback', { statusCode: 200, body: { token: 'mock_token', user: { id: '123', email: 'testuser@gmail.com', name: 'Test User' } } }).as('googleCallback');
