describe('Session Expiration after 30 minutes of inactivity', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.login('testuser@example.com', 'password123');
    cy.get('[data-testid="dashboard"]').should('be.visible');
  });

  it('should display session active indicator', () => {
    cy.get('[data-testid="session-status"]').should('contain', 'Active');
  });

  it('should expire session after 30 minutes of inactivity', () => {
    cy.clock();
    cy.get('[data-testid="dashboard"]').should('be.visible');
    cy.tick(30 * 60 * 1000);
    cy.get('[data-testid="session-expired-modal"]').should('be.visible');
    cy.get('[data-testid="session-expired-modal"]').should('contain', 'Your session has expired');
  });

  it('should redirect to login page after session expiration', () => {
    cy.clock();
    cy.tick(30 * 60 * 1000);
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
  });

  it('should reset inactivity timer on user activity', () => {
    cy.clock();
    cy.tick(15 * 60 * 1000);
    cy.get('[data-testid="dashboard"]').click();
    cy.tick(15 * 60 * 1000);
    cy.get('[data-testid="dashboard"]').should('be.visible');
    cy.get('[data-testid="session-expired-modal"]').should('not.exist');
  });

  it('should show warning before session expiration', () => {
    cy.clock();
    cy.tick(25 * 60 * 1000);
    cy.get('[data-testid="session-warning-banner"]').should('be.visible');
    cy.get('[data-testid="session-warning-banner"]').should('contain', 'Your session will expire in 5 minutes');
  });

  it('should allow extending session from warning', () => {
    cy.clock();
    cy.tick(25 * 60 * 1000);
    cy.get('[data-testid="extend-session-btn"]').click();
    cy.tick(5 * 60 * 1000);
    cy.get('[data-testid="dashboard"]').should('be.visible');
    cy.get('[data-testid="session-expired-modal"]').should('not.exist');
  });

  it('should clear session data after expiration', () => {
    cy.clock();
    cy.window().then((win) => {
      expect(win.sessionStorage.getItem('authToken')).to.exist;
    });
    cy.tick(30 * 60 * 1000);
    cy.window().then((win) => {
      expect(win.sessionStorage.getItem('authToken')).to.be.null;
    });
  });
});

