describe('Textarea Character Count Validation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display character count on textarea', () => {
    cy.get('textarea').should('be.visible');
    cy.get('[data-testid="char-count"]').should('contain', '0/500');
  });

  it('should update character count as user types', () => {
    cy.get('textarea').type('Hello World');
    cy.get('[data-testid="char-count"]').should('contain', '11/500');
  });

  it('should not allow more than 500 characters', () => {
    cy.get('textarea').invoke('val', 'a'.repeat(501)).trigger('input');
    cy.get('textarea').invoke('val').should('have.length', 500);
    cy.get('[data-testid="char-count"]').should('contain', '500/500');
  });

  it('should display warning when approaching limit', () => {
    cy.get('textarea').type('a'.repeat(450));
    cy.get('[data-testid="char-count"]').should('have.class', 'warning');
  });

  it('should display error when at limit', () => {
    cy.get('textarea').invoke('val', 'a'.repeat(500)).trigger('input');
    cy.get('[data-testid="char-count"]').should('have.class', 'error');
    cy.get('textarea').should('be.disabled');
  });

  it('should update count after clearing text', () => {
    cy.get('textarea').type('Sample text');
    cy.get('[data-testid="char-count"]').should('contain', '11/500');
    cy.get('textarea').clear();
    cy.get('[data-testid="char-count"]').should('contain', '0/500');
  });
});

