describe('Date Picker - Prevent Past Dates', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/booking');
  });

  it('should disable past dates in date picker', () => {
    cy.get('[data-testid="date-picker-input"]').click();
    cy.get('[data-testid="datepicker-calendar"]').should('be.visible');

    const today = new Date();
    const yesterday = new Date(today.getTime() - 24 * 60 * 60 * 1000);
    const yesterdayDate = yesterday.getDate();

    cy.get(`[data-testid="calendar-day-${yesterdayDate}"][aria-disabled="true"]`).should('exist');
  });

  it('should allow selecting future dates', () => {
    cy.get('[data-testid="date-picker-input"]').click();
    cy.get('[data-testid="datepicker-calendar"]').should('be.visible');

    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    const tomorrowDate = tomorrow.getDate();

    cy.get(`[data-testid="calendar-day-${tomorrowDate}"]`).should('not.have.attr', 'aria-disabled', 'true');
    cy.get(`[data-testid="calendar-day-${tomorrowDate}"]`).click();
    cy.get('[data-testid="date-picker-input"]').should('have.value', tomorrow.toISOString().split('T')[0]);
  });

  it('should display error message when trying to select past date', () => {
    cy.get('[data-testid="date-picker-input"]').type('2020-01-01');
    cy.get('[data-testid="booking-form"]').submit();
    cy.get('[data-testid="error-message"]').should('contain', 'Cannot select past dates');
  });

  it('should not allow manual input of past dates', () => {
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayStr = yesterday.toISOString().split('T')[0];

    cy.get('[data-testid="date-picker-input"]').type(yesterdayStr);
    cy.get('[data-testid="date-picker-input"]').should('have.value', '');
  });

  it('should allow today's date for future bookings', () => {
    cy.get('[data-testid="date-picker-input"]').click();

    const today = new Date();
    const todayDate = today.getDate();

    cy.get(`[data-testid="calendar-day-${todayDate}"]`).should('not.have.attr', 'aria-disabled', 'true');
    cy.get(`[data-testid="calendar-day-${todayDate}"]`).click();
    cy.get('[data-testid="booking-form"]').submit();
    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});

