describe('Form Data Persistence on Navigation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/form');
  });

  it('should persist form data when navigating away and back', () => {
    cy.get('input[name="firstName"]').type('John');
    cy.get('input[name="lastName"]').type('Doe');
    cy.get('input[name="email"]').type('john@example.com');
    cy.get('textarea[name="message"]').type('Test message');

    cy.get('a[href="/home"]').click();
    cy.url().should('include', '/home');

    cy.go('back');
    cy.url().should('include', '/form');

    cy.get('input[name="firstName"]').should('have.value', 'John');
    cy.get('input[name="lastName"]').should('have.value', 'Doe');
    cy.get('input[name="email"]').should('have.value', 'john@example.com');
    cy.get('textarea[name="message"]').should('have.value', 'Test message');
  });

  it('should persist form data using browser back button', () => {
    cy.get('input[name="username"]').type('testuser');
    cy.get('input[name="password"]').type('password123');
    cy.get('select[name="country"]').select('USA');

    cy.visit('http://localhost:3000/dashboard');
    cy.go('back');

    cy.get('input[name="username"]').should('have.value', 'testuser');
    cy.get('input[name="password"]').should('have.value', 'password123');
    cy.get('select[name="country"]').should('have.value', 'USA');
  });

  it('should persist checkbox and radio button states', () => {
    cy.get('input[type="checkbox"][name="subscribe"]').check();
    cy.get('input[type="radio"][name="plan"][value="premium"]').check();

    cy.get('a[href="/settings"]').click();
    cy.go('back');

    cy.get('input[type="checkbox"][name="subscribe"]').should('be.checked');
    cy.get('input[type="radio"][name="plan"][value="premium"]').should('be.checked');
  });

  it('should clear persisted data on form reset', () => {
    cy.get('input[name="firstName"]').type('Jane');
    cy.get('input[name="lastName"]').type('Smith');

    cy.get('button[type="reset"]').click();

    cy.get('input[name="firstName"]').should('have.value', '');
    cy.get('input[name="lastName"]').should('have.value', '');
  });
});

