describe('File Upload - Size Validation', () => {
  beforeEach(() => {
    cy.visit('/upload-form');
  });

  it('should reject files larger than 5MB', () => {
    const largeFileName = 'large-file.txt';
    const fileSize = 6 * 1024 * 1024;

    cy.fixture('large-file.txt', 'binary').then(fileContent => {
      cy.get('input[type="file"]').selectFile({
        contents: Cypress.Buffer.from('x'.repeat(fileSize)),
        fileName: largeFileName,
        mimeType: 'text/plain'
      }, { force: true });
    });

    cy.get('.error-message').should('be.visible');
    cy.get('.error-message').should('contain', 'File size must not exceed 5MB');
  });

  it('should accept files smaller than 5MB', () => {
    const smallFileName = 'small-file.txt';
    const fileSize = 2 * 1024 * 1024;

    cy.get('input[type="file"]').selectFile({
      contents: Cypress.Buffer.from('x'.repeat(fileSize)),
      fileName: smallFileName,
      mimeType: 'text/plain'
    }, { force: true });

    cy.get('.success-message').should('be.visible');
    cy.get('.success-message').should('contain', 'File uploaded successfully');
  });

  it('should reject file at exactly 5MB + 1 byte', () => {
    const fileSize = (5 * 1024 * 1024) + 1;

    cy.get('input[type="file"]').selectFile({
      contents: Cypress.Buffer.from('x'.repeat(fileSize)),
      fileName: 'boundary-file.txt',
      mimeType: 'text/plain'
    }, { force: true });

    cy.get('.error-message').should('be.visible');
    cy.get('.error-message').should('contain', 'File size must not exceed 5MB');
  });

  it('should accept file at exactly 5MB', () => {
    const fileSize = 5 * 1024 * 1024;

    cy.get('input[type="file"]').selectFile({
      contents: Cypress.Buffer.from('x'.repeat(fileSize)),
      fileName: 'boundary-file-valid.txt',
      mimeType: 'text/plain'
    }, { force: true });

    cy.get('.success-message').should('be.visible');
  });
});

