describe('Form Auto-Save Draft Feature', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should auto-save form as draft every 30 seconds', () => {
    cy.get('input[name="firstName"]').type('John');
    cy.get('input[name="lastName"]').type('Doe');
    cy.get('textarea[name="description"]').type('Test description');

    cy.window().then((win) => {
      const initialDraftTime = win.localStorage.getItem('formDraftTimestamp');
      expect(initialDraftTime).to.exist;
    });

    cy.wait(30000);

    cy.window().then((win) => {
      const draftData = JSON.parse(win.localStorage.getItem('formDraft'));
      expect(draftData.firstName).to.equal('John');
      expect(draftData.lastName).to.equal('Doe');
      expect(draftData.description).to.equal('Test description');
    });
  });

  it('should update draft timestamp after each auto-save interval', () => {
    cy.get('input[name="email"]').type('test@example.com');

    cy.window().then((win) => {
      const firstTimestamp = win.localStorage.getItem('formDraftTimestamp');
      cy.wrap(firstTimestamp).should('exist');

      cy.wait(30000).then(() => {
        const secondTimestamp = win.localStorage.getItem('formDraftTimestamp');
        expect(parseInt(secondTimestamp)).to.be.greaterThan(parseInt(firstTimestamp));
      });
    });
  });

  it('should display draft saved indicator on auto-save', () => {
    cy.get('input[name="title"]').type('My Title');
    cy.get('.auto-save-indicator').should('not.be.visible');

    cy.wait(30000);
    cy.get('.auto-save-indicator').should('be.visible');
    cy.get('.auto-save-indicator').should('contain', 'Draft saved');
    cy.wait(2000);
    cy.get('.auto-save-indicator').should('not.be.visible');
  });

  it('should recover form data from draft on page reload', () => {
    cy.get('input[name="firstName"]').type('Jane');
    cy.get('input[name="lastName"]').type('Smith');

    cy.wait(30000);
    cy.reload();

    cy.get('input[name="firstName"]').should('have.value', 'Jane');
    cy.get('input[name="lastName"]').should('have.value', 'Smith');
  });

  it('should clear draft when form is submitted', () => {
    cy.get('input[name="firstName"]').type('Test');
    cy.wait(30000);

    cy.window().then((win) => {
      const draftBefore = win.localStorage.getItem('formDraft');
      expect(draftBefore).to.exist;
    });

    cy.get('button[type="submit"]').click();

    cy.window().then((win) => {
      const draftAfter = win.localStorage.getItem('formDraft');
      expect(draftAfter).to.be.null;
    });
  });
});

