describe('Multi-step Form Navigation - Back Button', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/multi-step-form');
  });

  it('should preserve form data when navigating back to previous step', () => {
    // Step 1: Fill form data
    cy.get('input[name="firstName"]').type('John');
