    cy.get('input[name="address"]').type('123 Main St');

    // Click back button
    cy.get('button[data-testid="back-button"]').click();

    // Verify step 1 data is preserved
    cy.get('input[name="firstName"]').should('have.value', 'John');
    cy.get('input[name="lastName"]').should('have.value', 'Doe');
    cy.get('input[name="email"]').should('have.value', 'john@example.com');
  });

  it('should preserve data across multiple back and forward navigations', () => {
    cy.get('input[name="firstName"]').type('Jane');
    cy.get('input[name="lastName"]').type('Smith');
    cy.get('button[data-testid="next-button"]').click();

