    // Go forward
    cy.get('button[data-testid="next-button"]').click();
    cy.get('input[name="phone"]').should('have.value', '555-5678');
  });

  it('should not reset validation state when going back', () => {
    cy.get('button[data-testid="next-button"]').click();
