describe('Sticky Header Navigation', () => {
  beforeEach(() => {
    cy.visit('/')
  })

  it('should display sticky header at top of page', () => {
    cy.get('header').should('be.visible')
    cy.get('header').should('have.css', 'position', 'sticky')
  })

  it('should keep header visible when scrolling down', () => {
    cy.get('body').then(($body) => {
      const bodyHeight = $body.height()
      cy.get('header').then(($header) => {
        const headerHeight = $header.height()
        cy.get('header').should('have.css', 'top', '0px')
      })
    })
    cy.scrollTo(0, 500)
    cy.get('header').should('be.visible')
    cy.get('header').should('have.css', 'position', 'sticky')
  })

  it('should maintain header visibility at bottom of page', () => {
    cy.scrollTo('bottom')
    cy.get('header').should('be.visible')
    cy.get('header').scrollIntoView().should('be.visible')
  })

  it('should keep navigation links accessible while scrolling', () => {
    cy.get('header nav').should('be.visible')
    cy.scrollTo(0, 300)
    cy.get('header nav').should('be.visible')
    cy.get('header nav a').first().should('be.visible')
  })

  it('should not overlap page content when sticky', () => {
    cy.get('header').then(($header) => {
      const headerHeight = $header.outerHeight()
      cy.get('main').then(($main) => {
        const mainTop = $main[0].getBoundingClientRect().top
        cy.scrollTo(0, 200)
        cy.get('main').then(($mainAfterScroll) => {
          const mainTopAfter = $mainAfterScroll[0].getBoundingClientRect().top
          expect(mainTopAfter).to.be.gte(headerHeight)
        })
      })
    })
  })
})

