import { test, expect } from '@playwright/test';

test.describe('Sticky Header Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/')
  })

  test('should display sticky header at top of page', async ({ page }) => {
    const header = page.locator('header')
    await expect(header).toBeVisible()
    const position = await header.evaluate(el => window.getComputedStyle(el).position)
    expect(position).toBe('sticky')
  })

  test('should keep header visible when scrolling down', async ({ page }) => {
    const header = page.locator('header')
    await expect(header).toBeVisible()
    const position = await header.evaluate(el => window.getComputedStyle(el).position)
    expect(position).toBe('sticky')

    await page.evaluate(() => window.scrollBy(0, 500))
    await expect(header).toBeVisible()
  })

  test('should maintain header visibility at bottom of page', async ({ page }) => {
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight))
    const header = page.locator('header')
    await expect(header).toBeVisible()
  })

  test('should keep navigation links accessible while scrolling', async ({ page }) => {
    const nav = page.locator('header nav')
    await expect(nav).toBeVisible()

    await page.evaluate(() => window.scrollBy(0, 300))
    await expect(nav).toBeVisible()

    const firstLink = page.locator('header nav a').first()
    await expect(firstLink).toBeVisible()
  })

  test('should not overlap page content when sticky', async ({ page }) => {
    const header = page.locator('header')
    const headerBox = await header.boundingBox()
    const headerHeight = headerBox.height

    await page.evaluate(() => window.scrollBy(0, 200))

    const mainContent = page.locator('main')
    const mainBox = await mainContent.boundingBox()

    expect(mainBox.y).toBeGreaterThanOrEqual(headerHeight - 1)
  })
})

