describe('Loading Skeleton - API Data Fetching', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display loading skeleton while API data is fetching', () => {
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(2000);
      });
    }).as('fetchData');

    cy.get('[data-testid="loading-skeleton"]').should('be.visible');
    cy.get('[data-testid="skeleton-item"]').should('have.length.greaterThan', 0);
    cy.wait('@fetchData');
    cy.get('[data-testid="loading-skeleton"]').should('not.exist');
  });

  it('should hide skeleton and display content after API responds', () => {
    cy.intercept('GET', '/api/data', { fixture: 'data.json' }).as('fetchData');

    cy.get('[data-testid="loading-skeleton"]').should('be.visible');
    cy.wait('@fetchData');
    cy.get('[data-testid="loading-skeleton"]').should('not.be.visible');
    cy.get('[data-testid="content-item"]').should('be.visible');
  });

  it('should show skeleton with correct animation classes', () => {
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(1500);
      });
    }).as('fetchData');

    cy.get('[data-testid="skeleton-item"]')
      .first()
      .should('have.class', 'skeleton-loading');
    cy.get('[data-testid="skeleton-item"]')
      .first()
      .should('have.css', 'animation');
    cy.wait('@fetchData');
  });

  it('should handle multiple skeleton items during loading', () => {
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(2000);
      });
    }).as('fetchData');

    cy.get('[data-testid="skeleton-item"]').each(($item) => {
      cy.wrap($item).should('be.visible');
    });
    cy.wait('@fetchData');
    cy.get('[data-testid="skeleton-item"]').should('not.exist');
  });

  it('should show skeleton on page refresh with slow network', () => {
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(1000);
      });
    }).as('fetchData');

    cy.reload();
    cy.get('[data-testid="loading-skeleton"]').should('be.visible');
    cy.wait('@fetchData');
    cy.get('[data-testid="loading-skeleton"]').should('not.be.visible');
  });
});

