import { test, expect } from '@playwright/test';

test.describe('Loading Skeleton - API Data Fetching', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display loading skeleton while API data is fetching', async ({ page }) => {
    await page.route('**/api/data', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 2000));
      await route.continue();
    });

    const skeleton = page.locator('[data-testid="loading-skeleton"]');
    const skeletonItems = page.locator('[data-testid="skeleton-item"]');

    await expect(skeleton).toBeVisible();
    await expect(skeletonItems).toHaveCount(await skeletonItems.count());
    await expect(skeletonItems.first()).toBeVisible();
    await page.waitForFunction(() => !document.querySelector('[data-testid="loading-skeleton"]'));
  });

  test('should hide skeleton and display content after API responds', async ({ page }) => {
    await page.route('**/api/data', route => {
      route.abort();
    });

    const skeleton = page.locator('[data-testid="loading-skeleton"]');
    await expect(skeleton).toBeVisible();

    await page.route('**/api/data', route => {
      route.continue();
    });

    await page.waitForFunction(() => !document.querySelector('[data-testid="loading-skeleton"]'));
    const content = page.locator('[data-testid="content-item"]');
    await expect(content.first()).toBeVisible();
  });

  test('should show skeleton with correct animation classes', async ({ page }) => {
    await page.route('**/api/data', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 1500));
      await route.continue();
    });

    const skeletonItem = page.locator('[data-testid="skeleton-item"]').first();
    await expect(skeletonItem).toHaveClass(/skeleton-loading/);

    const styles = await skeletonItem.evaluate(el => window.getComputedStyle(el).animation);
    expect(styles).toBeTruthy();
  });

  test('should handle multiple skeleton items during loading', async ({ page }) => {
    await page.route('**/api/data', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 2000));
      await route.continue();
    });

    const skeletonItems = page.locator('[data-testid="skeleton-item"]');
    const count = await skeletonItems.count();
    expect(count).toBeGreaterThan(0);

    for (let i = 0; i < count; i++) {
      await expect(skeletonItems.nth(i)).toBeVisible();
    }

    await page.waitForFunction(() => !document.querySelector('[data-testid="skeleton-item"]'));
  });

  test('should show skeleton on page refresh with slow network', async ({ page }) => {
    await page.route('**/api/data', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 1000));
      await route.continue();
    });

    await page.reload();
    const skeleton = page.locator('[data-testid="loading-skeleton"]');
    await expect(skeleton).toBeVisible();

    await page.waitForFunction(() => !document.querySelector('[data-testid="loading-skeleton"]'));
    await expect(skeleton).not.toBeVisible();
  });
});

