    const refreshPromise = page.waitForResponse(response => response.url().includes('/api/data') && response.status() === 200);
    await refreshPromise;
    await expect(dataDisplay).toContainText('Updated Value');
  });

  test('should show loading state during data refresh', async ({ page }) => {
    await page.goto('http://localhost:3000');
    await page.waitForResponse(response => response.url().includes('/api/data'));
    const loadingSpinner = page.locator('[data-testid="loading-spinner"]');
    const updateButton = page.locator('[data-testid="update-button"]');
