    await expect(loadingSpinner).not.toBeVisible();
  });

  test('should handle refresh failure gracefully', async ({ page }) => {
    await page.route('**/api/data/update', route => {
      route.abort('failed');
    });
    await page.goto('http://localhost:3000');
