describe('Optimistic UI Updates - Like Post', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.login('testuser@example.com', 'password123');
  });

  it('should show like count increment immediately before API response', () => {
    cy.get('[data-testid="post-1"]').within(() => {
      cy.get('[data-testid="like-count"]').should('have.text', '10');
      cy.get('[data-testid="like-button"]').click();
      cy.get('[data-testid="like-count"]').should('have.text', '11');
    });
  });

  it('should revert like count if API fails', () => {
    cy.intercept('POST', '/api/posts/1/like', { statusCode: 500 });
    cy.get('[data-testid="post-1"]').within(() => {
      cy.get('[data-testid="like-count"]').should('have.text', '10');
      cy.get('[data-testid="like-button"]').click();
      cy.get('[data-testid="like-count"]').should('have.text', '11');
      cy.wait('@likePost');
      cy.get('[data-testid="like-count"]').should('have.text', '10');
    });
  });

  it('should maintain like state after successful API response', () => {
    cy.intercept('POST', '/api/posts/1/like', { statusCode: 200, body: { liked: true, count: 11 } }).as('likePost');
    cy.get('[data-testid="post-1"]').within(() => {
      cy.get('[data-testid="like-button"]').click();
      cy.get('[data-testid="like-count"]').should('have.text', '11');
      cy.wait('@likePost');
      cy.get('[data-testid="like-count"]').should('have.text', '11');
      cy.get('[data-testid="like-button"]').should('have.class', 'liked');
    });
  });

  it('should show error message on like failure', () => {
    cy.intercept('POST', '/api/posts/1/like', { statusCode: 500, body: { error: 'Failed to like post' } }).as('likePost');
    cy.get('[data-testid="post-1"]').within(() => {
      cy.get('[data-testid="like-button"]').click();
      cy.wait('@likePost');
      cy.get('[data-testid="error-message"]').should('contain', 'Failed to like');
    });
  });

  it('should disable like button during API request', () => {
    cy.intercept('POST', '/api/posts/1/like', (req) => {
      req.reply((res) => {
        res.delay(1000);
        res.send({ statusCode: 200, body: { liked: true, count: 11 } });
      });
    }).as('likePost');
    cy.get('[data-testid="post-1"]').within(() => {
      cy.get('[data-testid="like-button"]').click();
      cy.get('[data-testid="like-button"]').should('be.disabled');
      cy.wait('@likePost');
      cy.get('[data-testid="like-button"]').should('not.be.disabled');
    });
  });
});

