describe('Stale Data Invalidation After Form Submission', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.intercept('GET', '/api/data', { fixture: 'initial-data.json' }).as('getData');
    cy.intercept('POST', '/api/form-submit', { statusCode: 200, body: { success: true } }).as('formSubmit');
  });

  it('should invalidate cached data after successful form submission', () => {
    cy.wait('@getData');
    cy.get('[data-cy=form-input]').type('new value');
    cy.get('[data-cy=submit-btn]').click();
    cy.wait('@formSubmit');

    cy.intercept('GET', '/api/data', { fixture: 'updated-data.json' }).as('getUpdatedData');
    cy.get('[data-cy=refresh-btn]').click();
    cy.wait('@getUpdatedData');

    cy.get('[data-cy=data-display]').should('contain', 'updated content');
  });

  it('should not use stale cache after POST request', () => {
    let initialRequestCount = 0;
    cy.intercept('GET', '/api/data', (req) => {
      initialRequestCount++;
      req.reply({ fixture: 'initial-data.json' });
    }).as('dataRequest');

    cy.get('[data-cy=form-input]').type('test');
    cy.get('[data-cy=submit-btn]').click();

    cy.intercept('GET', '/api/data', (req) => {
      req.reply({ fixture: 'updated-data.json' });
    });

    cy.get('[data-cy=data-display]').invoke('text').then((text) => {
      expect(text).not.to.equal('stale value');
    });
  });

  it('should clear local storage cache on form submission success', () => {
    cy.window().then((win) => {
      win.localStorage.setItem('cached_data', JSON.stringify({ value: 'old' }));
    });

    cy.get('[data-cy=form-input]').type('new value');
    cy.get('[data-cy=submit-btn]').click();
    cy.wait('@formSubmit');

    cy.window().then((win) => {
      const cached = win.localStorage.getItem('cached_data');
      expect(cached).to.be.null;
    });
  });
});

