describe('Search Results Debounce', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.intercept('GET', '**/api/search*').as('searchRequest');
  });

  it('should debounce search requests by 300ms', () => {
    cy.get('[data-testid="search-input"]').as('searchInput');

    cy.get('@searchInput').type('t');
    cy.wait(100);
    cy.get('@searchInput').type('e');
    cy.wait(100);
    cy.get('@searchInput').type('s');
    cy.wait(100);
    cy.get('@searchInput').type('t');

