      expect(interception.request.url).to.include('test');
    });

    cy.get('[data-testid="search-results"]').should('exist');
  });

  it('should only send one request after debounce period', () => {
    let requestCount = 0;
    cy.intercept('GET', '**/api/search*', () => {
      requestCount++;
    }).as('searchRequest');

    cy.get('[data-testid="search-input"]').type('query', { delay: 50 });
    cy.wait(400);

    cy.get('@searchRequest.all').then((interceptions) => {
      expect(interceptions.length).to.equal(1);
    });
  });

  it('should update results when debounce completes', () => {
    cy.intercept('GET', '**/api/search?q=cypress', {
