  it('should not show results before debounce time', () => {
    cy.get('[data-testid="search-input"]').type('test');
    cy.get('[data-testid="search-results"]').should('not.exist');
    cy.wait(300);
    cy.get('[data-testid="search-results"]').should('exist');
  });
});

