    await context.addInitScript(() => {
      localStorage.setItem('authToken', 'valid-token-123');
    });

    await page.route('**/api/data', async route => {
      await route.respond({
        status: 401,
        body: JSON.stringify({ error: 'Unauthorized' })
      });
