describe('Polling stops when navigating away from page', () => {
  let pollCount = 0;
  const pollInterval = 2000;

  beforeEach(() => {
    cy.intercept('GET', '/api/poll', (req) => {
      pollCount++;
      req.reply({
        statusCode: 200,
        body: { status: 'active', data: 'test' }
      });
    }).as('pollRequest');
    cy.visit('http://localhost:3000/polling-page');
  });

  it('should stop polling requests when user navigates away', () => {
    cy.window().then((win) => {
      pollCount = 0;
    });

    cy.wait('@pollRequest', { timeout: 5000 });
    cy.get('[data-testid="poll-status"]').should('contain', 'active');
    cy.wait(pollInterval + 1000);
    cy.wait('@pollRequest');

    const countBeforeNav = pollCount;
    cy.log(`Poll count before navigation: ${countBeforeNav}`);

    cy.get('[data-testid="navigate-button"]').click();
    cy.url().should('include', '/other-page');

    cy.wait(pollInterval * 3, { requestTimeout: 1000 }).then(() => {
      cy.get('@pollRequest.all').then((requests) => {
        const countAfterNav = requests.length;
        expect(countAfterNav).to.equal(countBeforeNav);
      });
    });
  });

  it('should resume polling when returning to the page', () => {
    cy.wait('@pollRequest');
    cy.get('[data-testid="navigate-button"]').click();
    cy.url().should('include', '/other-page');

    cy.get('[data-testid="back-button"]').click();
    cy.url().should('include', '/polling-page');

    cy.wait('@pollRequest', { timeout: 5000 });
    cy.get('[data-testid="poll-status"]').should('exist');
  });

  it('should clear polling interval on component unmount', () => {
    cy.intercept('GET', '/api/poll').as('pollRequest');
    cy.wait('@pollRequest');

    cy.window().then((win) => {
      const setIntervalSpy = cy.spy(win, 'setInterval');
      const clearIntervalSpy = cy.spy(win, 'clearInterval');
    });

    cy.get('[data-testid="navigate-button"]').click();
    cy.get('@clearIntervalSpy.called').should('equal', true);
  });
});

