import { test, expect, Page } from '@playwright/test';

test.describe('Polling stops when navigating away from page', () => {
  let pollCount = 0;
  const pollInterval = 2000;
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    pollCount = 0;

    await page.route('/api/poll', (route) => {
      pollCount++;
      route.abort();
    });
  });

  test.afterEach(async () => {
    await page.close();
  });

  test('should stop polling requests when user navigates away', async () => {
    await page.goto('http://localhost:3000/polling-page');

    const pollRequestsSpy = page.on('request', (request) => {
      if (request.url().includes('/api/poll')) {
        pollCount++;
      }
    });

    await page.waitForURL(/polling-page/, { timeout: 5000 });
    const pollStatusElement = await page.locator('[data-testid="poll-status"]');
    await expect(pollStatusElement).toContainText('active');

    const countBeforeNav = pollCount;
    await page.waitForTimeout(pollInterval + 1000);

    await page.click('[data-testid="navigate-button"]');
    await page.waitForURL(/other-page/, { timeout: 5000 });

    const countAfterNav = pollCount;
    await page.waitForTimeout(pollInterval * 3);

    expect(pollCount).toBeLessThanOrEqual(countBeforeNav + 1);
  });

  test('should resume polling when returning to the page', async () => {
    await page.goto('http://localhost:3000/polling-page');

    await page.waitForURL(/polling-page/, { timeout: 5000 });
    const countBefore = pollCount;

    await page.click('[data-testid="navigate-button"]');
    await page.waitForURL(/other-page/, { timeout: 5000 });

    await page.click('[data-testid="back-button"]');
    await page.waitForURL(/polling-page/, { timeout: 5000 });

    await page.waitForTimeout(pollInterval + 1000);
    const pollStatusElement = await page.locator('[data-testid="poll-status"]');
    await expect(pollStatusElement).toBeVisible();

    expect(pollCount).toBeGreaterThan(countBefore);
  });

  test('should clear polling interval on page unload', async () => {
    await page.goto('http://localhost:3000/polling-page');

    const consoleMessages: string[] = [];
    page.on('console', (msg) => {
      if (msg.text().includes('polling')) {
        consoleMessages.push(msg.text());
      }
    });

    await page.evaluate(() => {
      window.addEventListener('beforeunload', () => {
        console.log('polling cleanup');
      });
    });

    await page.click('[data-testid="navigate-button"]');
    await page.waitForURL(/other-page/, { timeout: 5000 });

    expect(consoleMessages.some(msg => msg.includes('cleanup'))).toBeTruthy();
  });

  test('should not make poll requests during navigation transition', async () => {
    await page.goto('http://localhost:3000/polling-page');

    const pollRequests: number[] = [];
    page.on('request', (request) => {
      if (request.url().includes('/api/poll')) {
        pollRequests.push(Date.now());
      }
    });

    const beforeNavTime = Date.now();
    await page.click('[data-testid="navigate-button"]');
    const afterNavTime = Date.now();

    const requestsDuringNav = pollRequests.filter(
      (time) => time >= beforeNavTime && time <= afterNavTime
    );

    expect(requestsDuringNav.length).toBeLessThanOrEqual(1);
  });
});

