import { test, expect } from '@playwright/test';

test.describe('API Response Caching', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should cache API response on first visit', async ({ page }) => {
    let requestCount = 0;
    page.on('request', request => {
      if (request.url().includes('/api/data')) {
        requestCount++;
      }
    });
    await page.waitForLoadState('networkidle');
    expect(requestCount).toBe(1);
  });

  test('should return cached response on repeat visit without network call', async ({ page }) => {
    let firstVisitRequests = 0;
    let secondVisitRequests = 0;

    page.on('request', request => {
      if (request.url().includes('/api/data')) {
        firstVisitRequests++;
      }
    });

    await page.waitForLoadState('networkidle');
    await expect(page.locator('[data-testid="content"]')).toBeVisible();

    page.removeAllListeners('request');
    page.on('request', request => {
      if (request.url().includes('/api/data')) {
        secondVisitRequests++;
      }
    });

    await page.locator('[data-testid="refresh-button"]').click();
    await page.waitForTimeout(500);
    expect(secondVisitRequests).toBe(0);
  });

  test('should display cached data instantly on repeat visit', async ({ page }) => {
    await page.waitForLoadState('networkidle');
    const startTime = Date.now();
    await page.reload();
    await expect(page.locator('[data-testid="content"]')).toBeVisible();
    const loadTime = Date.now() - startTime;
    expect(loadTime).toBeLessThan(500);
  });

  test('should validate cache headers are set correctly', async ({ page }) => {
    const responses = [];
    page.on('response', response => {
      if (response.url().includes('/api/data')) {
        responses.push(response);
      }
    });
    await page.waitForLoadState('networkidle');
    expect(responses.length).toBeGreaterThan(0);
    const cacheControl = responses[0].headers()['cache-control'];
    expect(cacheControl).toBeDefined();
    expect(cacheControl).toContain('max-age');
  });

  test('should clear cache when cache clear button is clicked', async ({ page }) => {
    await page.waitForLoadState('networkidle');
    await page.locator('[data-testid="clear-cache-button"]').click();

    let requestCount = 0;
    page.on('request', request => {
      if (request.url().includes('/api/data')) {
        requestCount++;
      }
    });

    await page.locator('[data-testid="refresh-button"]').click();
    await page.waitForLoadState('networkidle');
    expect(requestCount).toBeGreaterThan(0);
    await expect(page.locator('[data-testid="content"]')).toBeVisible();
  });
});

