describe('Stale Record Conflict Error Message', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.login('testuser', 'password');
  });

  it('should display conflict error message when saving a stale record', () => {
    cy.intercept('GET', '/api/records/123', {
      statusCode: 200,
      body: { id: 123, name: 'Test Record', version: 1, data: 'original' }
    }).as('getRecord');

    cy.intercept('PUT', '/api/records/123', (req) => {
      if (req.body.version < 2) {
        req.reply({
          statusCode: 409,
          body: { error: 'Conflict: Record has been modified. Please refresh and try again.' }
        });
      }
    }).as('updateRecord');

    cy.get('[data-testid="record-edit-btn"]').click();
    cy.wait('@getRecord');
    cy.get('[data-testid="record-name-input"]').clear().type('Updated Name');
    cy.get('[data-testid="record-save-btn"]').click();
    cy.wait('@updateRecord');

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Conflict: Record has been modified');
  });

  it('should show conflict error with correct status code 409', () => {
    cy.intercept('PUT', '/api/records/456', {
      statusCode: 409,
      body: { error: 'Conflict: Stale record version' }
    }).as('conflictUpdate');

    cy.visit('http://localhost:3000/records/456/edit');
    cy.get('[data-testid="record-save-btn"]').click();
    cy.wait('@conflictUpdate');

    cy.get('[data-testid="error-toast"]').should('exist');
    cy.get('[data-testid="error-toast"]').should('have.class', 'error');
  });

  it('should not save record when conflict error is received', () => {
    const saveSpy = cy.spy();
    cy.intercept('PUT', '/api/records/**', (req) => {
      saveSpy();
      req.reply({
        statusCode: 409,
        body: { error: 'Record conflict' }
      });
    });

    cy.get('[data-testid="record-save-btn"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});

