describe('Duplicate Record Feature', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.login('testuser', 'password');
  });

  it('should duplicate an existing record with one click', () => {
    cy.get('[data-testid="record-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').first().as('firstRecord');
    cy.get('@firstRecord').invoke('attr', 'data-record-id').as('originalId');
    cy.get('@firstRecord').within(() => {
      cy.get('[data-testid="duplicate-btn"]').click();
    });
    cy.get('[data-testid="success-toast"]').should('contain', 'Record duplicated successfully');
    cy.get('[data-testid="record-list"]').children().should('have.length.greaterThan', 1);
    cy.get('[data-testid="record-item"]').last().should('contain', cy.get('@firstRecord').invoke('text'));
  });

  it('should display duplicate confirmation for large records', () => {
    cy.get('[data-testid="record-item"][data-size="large"]').first().as('largeRecord');
    cy.get('@largeRecord').within(() => {
      cy.get('[data-testid="duplicate-btn"]').click();
    });
    cy.get('[data-testid="confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-duplicate"]').click();
    cy.get('[data-testid="success-toast"]').should('be.visible');
  });

  it('should maintain all record properties when duplicating', () => {
    cy.get('[data-testid="record-item"]').first().as('originalRecord');
    cy.get('@originalRecord').invoke('attr', 'data-record-data').as('originalData');
    cy.get('@originalRecord').within(() => {
      cy.get('[data-testid="duplicate-btn"]').click();
    });
    cy.wait(500);
    cy.get('[data-testid="record-item"]').last().as('duplicatedRecord');
    cy.get('@duplicatedRecord').invoke('attr', 'data-record-data').then((duplicatedData) => {
      expect(duplicatedData).to.equal(cy.get('@originalData'));
    });
  });

  it('should disable duplicate button for restricted records', () => {
    cy.get('[data-testid="record-item"][data-restricted="true"]').first().as('restrictedRecord');
    cy.get('@restrictedRecord').within(() => {
      cy.get('[data-testid="duplicate-btn"]').should('be.disabled');
    });
  });
});

