describe('Inline Editing on Table Row', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('table').should('be.visible');
  });

  it('should enable inline editing when clicking on a table cell', () => {
    cy.get('table tbody tr').first().find('td').eq(1).click();
    cy.get('table tbody tr').first().find('td').eq(1).find('input').should('be.visible');
  });

  it('should update cell value and persist changes on blur', () => {
    cy.get('table tbody tr').first().find('td').eq(1).click();
    cy.get('table tbody tr').first().find('td').eq(1).find('input').clear().type('Updated Value');
    cy.get('table tbody tr').first().find('td').eq(1).find('input').blur();
    cy.get('table tbody tr').first().find('td').eq(1).should('contain', 'Updated Value');
  });

  it('should cancel editing on escape key', () => {
    const originalValue = cy.get('table tbody tr').first().find('td').eq(1).invoke('text');
    cy.get('table tbody tr').first().find('td').eq(1).click();
    cy.get('table tbody tr').first().find('td').eq(1).find('input').clear().type('Cancelled Value');
    cy.get('table tbody tr').first().find('td').eq(1).find('input').type('{esc}');
    cy.get('table tbody tr').first().find('td').eq(1).should('not.contain', 'Cancelled Value');
  });

  it('should edit multiple cells in the same row sequentially', () => {
    cy.get('table tbody tr').first().find('td').eq(1).click();
    cy.get('table tbody tr').first().find('td').eq(1).find('input').clear().type('Cell 1 Updated');
    cy.get('table tbody tr').first().find('td').eq(1).find('input').blur();
    cy.get('table tbody tr').first().find('td').eq(2).click();
    cy.get('table tbody tr').first().find('td').eq(2).find('input').clear().type('Cell 2 Updated');
    cy.get('table tbody tr').first().find('td').eq(2).find('input').blur();
    cy.get('table tbody tr').first().find('td').eq(1).should('contain', 'Cell 1 Updated');
    cy.get('table tbody tr').first().find('td').eq(2).should('contain', 'Cell 2 Updated');
  });

  it('should show validation error for invalid input', () => {
    cy.get('table tbody tr').first().find('td').eq(1).click();
    cy.get('table tbody tr').first().find('td').eq(1).find('input').clear().type('123');
    cy.get('table tbody tr').first().find('td').eq(1).find('input').blur();
    cy.get('[role="alert"]').should('contain', 'Invalid input');
  });

  it('should not allow editing on disabled rows', () => {
    cy.get('table tbody tr').filter('[data-disabled="true"]').first().find('td').eq(1).click();
    cy.get('table tbody tr').filter('[data-disabled="true"]').first().find('td').eq(1).find('input').should('not.exist');
  });
});

