describe('Reorder list items by drag and drop', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should reorder list items when dragging and dropping', () => {
    cy.get('[data-testid="list-item"]:nth-child(1)').should('contain', 'Item 1');
    cy.get('[data-testid="list-item"]:nth-child(2)').should('contain', 'Item 2');
    cy.get('[data-testid="list-item"]:nth-child(3)').should('contain', 'Item 3');

    cy.get('[data-testid="list-item"]:nth-child(1)')
      .trigger('mousedown')
      .trigger('dragstart')
      .trigger('drag');

    cy.get('[data-testid="list-item"]:nth-child(3)')
      .trigger('dragover')
      .trigger('drop')
      .trigger('dragend');

    cy.get('[data-testid="list-item"]:nth-child(1)').should('contain', 'Item 2');
    cy.get('[data-testid="list-item"]:nth-child(3)').should('contain', 'Item 1');
  });

  it('should maintain list integrity after multiple drag and drop operations', () => {
    cy.get('[data-testid="list-item"]').should('have.length', 3);

    cy.get('[data-testid="list-item"]:nth-child(1)').trigger('mousedown').trigger('dragstart');
    cy.get('[data-testid="list-item"]:nth-child(2)').trigger('dragover').trigger('drop').trigger('dragend');

    cy.get('[data-testid="list-item"]').should('have.length', 3);
    cy.get('[data-testid="list-item"]:nth-child(1)').should('exist');
    cy.get('[data-testid="list-item"]:nth-child(2)').should('exist');
    cy.get('[data-testid="list-item"]:nth-child(3)').should('exist');
  });

  it('should persist reordered list items after page reload', () => {
    cy.get('[data-testid="list-item"]:nth-child(1)').trigger('mousedown').trigger('dragstart');
    cy.get('[data-testid="list-item"]:nth-child(3)').trigger('dragover').trigger('drop').trigger('dragend');

    cy.reload();

    cy.get('[data-testid="list-item"]:nth-child(1)').should('contain', 'Item 2');
    cy.get('[data-testid="list-item"]:nth-child(3)').should('contain', 'Item 1');
  });

  it('should not reorder when dragging outside valid drop zone', () => {
    const initialOrder = [];
    cy.get('[data-testid="list-item"]').each(($el) => {
      initialOrder.push($el.text());
    });

    cy.get('[data-testid="list-item"]:nth-child(1)').trigger('mousedown').trigger('dragstart');
    cy.get('body').trigger('dragover').trigger('dragend');

    cy.get('[data-testid="list-item"]:nth-child(1)').should('contain', initialOrder[0]);
  });
});

