    await expect(item3).toContainText('Item 3');

    await item1.dragTo(item3);

    const reorderedItem1 = page.locator('[data-testid="list-item"]').nth(0);
    const reorderedItem3 = page.locator('[data-testid="list-item"]').nth(2);

    await expect(reorderedItem1).toContainText('Item 2');
    await expect(reorderedItem3).toContainText('Item 1');
  });

  test('should maintain list integrity after multiple drag and drop operations', async ({ page }) => {
    let listItems = page.locator('[data-testid="list-item"]');
    await expect(listItems).toHaveCount(3);

    const item1 = page.locator('[data-testid="list-item"]').nth(0);
    const item2 = page.locator('[data-testid="list-item"]').nth(1);

    await item1.dragTo(item2);

    listItems = page.locator('[data-testid="list-item"]');
    await expect(listItems).toHaveCount(3);
  });

  test('should persist reordered list items after page reload', async ({ page }) => {
    const item1 = page.locator('[data-testid="list-item"]').nth(0);
    const item3 = page.locator('[data-testid="list-item"]').nth(2);

    await item1.dragTo(item3);

    await page.reload();

    const reorderedItem1 = page.locator('[data-testid="list-item"]').nth(0);
    const reorderedItem3 = page.locator('[data-testid="list-item"]').nth(2);

    await expect(reorderedItem1).toContainText('Item 2');
    await expect(reorderedItem3).toContainText('Item 1');
  });

  test('should not reorder when dragging outside valid drop zone', async ({ page }) => {
    const item1 = page.locator('[data-testid="list-item"]').nth(0);
    const initialText = await item1.textContent();

    await item1.hover();
    await page.mouse.down();
    await page.mouse.move(0, 0);
    await page.mouse.up();

    const currentText = await item1.textContent();
    expect(currentText).toBe(initialText);
  });
});

