describe('Mark Record as Favourite', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.login('testuser', 'password');
  });

  it('should mark a record as favourite', () => {
    cy.get('[data-testid="record-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').first().as('firstRecord');
    cy.get('@firstRecord').find('[data-testid="favourite-btn"]').click();
    cy.get('@firstRecord').find('[data-testid="favourite-icon"]').should('have.class', 'active');
  });

  it('should unmark a record as favourite', () => {
    cy.get('[data-testid="record-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').first().as('firstRecord');
    cy.get('@firstRecord').find('[data-testid="favourite-btn"]').click();
    cy.get('@firstRecord').find('[data-testid="favourite-icon"]').should('have.class', 'active');
