    cy.get('@firstRecord').find('[data-testid="favourite-icon"]').should('not.have.class', 'active');
  });

  it('should persist favourite status after page reload', () => {
    cy.get('[data-testid="record-item"]').first().find('[data-testid="favourite-btn"]').click();
