describe('Timeout Error Display', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display timeout error when request exceeds 10 seconds', () => {
    cy.intercept('GET', '/api/slow-endpoint', (req) => {
      req.reply((res) => {
        res.delay(11000);
        res.send({ statusCode: 200, body: { data: 'test' } });
      });
    }).as('slowRequest');

    cy.get('[data-testid="trigger-request-btn"]').click();
    cy.wait('@slowRequest');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Request timeout');
  });

  it('should not show timeout error when request completes within 10 seconds', () => {
    cy.intercept('GET', '/api/fast-endpoint', (req) => {
      req.reply((res) => {
        res.delay(5000);
        res.send({ statusCode: 200, body: { data: 'test' } });
      });
    }).as('fastRequest');

    cy.get('[data-testid="trigger-request-btn"]').click();
    cy.wait('@fastRequest');
    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should display user-friendly timeout error message', () => {
    cy.intercept('GET', '/api/slow-endpoint', (req) => {
      req.reply((res) => {
        res.delay(15000);
      });
    }).as('timedOutRequest');

    cy.get('[data-testid="trigger-request-btn"]').click();
    cy.get('[data-testid="error-message"]', { timeout: 15000 }).should('contain', 'The request took too long. Please try again.');
    cy.get('[data-testid="error-icon"]').should('be.visible');
  });
});

