describe('Permissions Error - Edit Another User Content', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.get('input[name="email"]').type('user1@test.com');
    cy.get('input[name="password"]').type('password123');
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');
  });

  it('should display permissions error when trying to edit another user content', () => {
    cy.visit('/content/456');
    cy.get('button[aria-label="Edit"]').click();
    cy.get('.error-message').should('be.visible');
    cy.get('.error-message').should('contain', 'You do not have permission to edit this content');
  });

  it('should prevent form submission when user lacks edit permissions', () => {
    cy.visit('/content/456/edit');
    cy.get('input[name="title"]').should('be.disabled');
    cy.get('button[type="submit"]').should('be.disabled');
    cy.get('.permission-denied-banner').should('contain', 'Access Denied');
  });

  it('should show error on direct API call to edit another user content', () => {
    cy.request({
      method: 'PUT',
      url: '/api/content/456',
      body: { title: 'Hacked' },
      failOnStatusCode: false
    }).then((response) => {
      expect(response.status).to.equal(403);
      expect(response.body.error).to.include('permission');
    });
  });

  it('should redirect to content detail page after dismissing error', () => {
    cy.visit('/content/456/edit');
    cy.get('.error-message button[aria-label="Close"]').click();
    cy.url().should('include', '/content/456');
  });
});

