describe('Error Boundary - UI Crash Handling', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display fallback screen when component throws error', () => {
    cy.get('[data-testid="trigger-error"]').click();
    cy.get('[data-testid="error-boundary-fallback"]').should('be.visible');
    cy.contains('Something went wrong').should('exist');
  });

  it('should show error message in fallback screen', () => {
    cy.get('[data-testid="trigger-error"]').click();
    cy.get('[data-testid="error-message"]').should('contain', 'Error');
  });

  it('should provide reset button to recover from error state', () => {
    cy.get('[data-testid="trigger-error"]').click();
    cy.get('[data-testid="error-boundary-fallback"]').should('be.visible');
    cy.get('[data-testid="reset-error-button"]').click();
    cy.get('[data-testid="error-boundary-fallback"]').should('not.exist');
    cy.get('[data-testid="main-content"]').should('be.visible');
  });

  it('should log error to console when component crashes', () => {
    const logs = [];
    cy.on('window:log', (log) => {
      logs.push(log);
    });
    cy.get('[data-testid="trigger-error"]').click();
    cy.get('[data-testid="error-boundary-fallback"]').should('be.visible');
  });

  it('should not crash entire application when nested component fails', () => {
    cy.get('[data-testid="nested-component-error"]').click();
    cy.get('[data-testid="error-boundary-fallback"]').should('be.visible');
    cy.get('[data-testid="nav-bar"]').should('be.visible');
    cy.get('[data-testid="footer"]').should('be.visible');
  });
});

