describe('Rate Limit Error on Form Submission', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/form');
  });

  it('should display rate-limit error after multiple rapid form submissions', () => {
    const submitCount = 6;
    const rateLimit = 5;

    for (let i = 0; i < submitCount; i++) {
      cy.get('input[name="email"]').clear().type(`test${i}@example.com`);
      cy.get('button[type="submit"]').click();
    }

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Too many requests');
  });

  it('should show specific rate-limit error code', () => {
    for (let i = 0; i < 6; i++) {
      cy.get('input[name="email"]').clear().type(`user${i}@test.com`);
      cy.get('button[type="submit"]').click();
    }

    cy.get('[data-testid="error-code"]')
      .should('contain', '429');
  });

  it('should display retry-after time in rate-limit error', () => {
    for (let i = 0; i < 6; i++) {
      cy.get('input[name="email"]').clear().type(`bulk${i}@mail.com`);
      cy.get('button[type="submit"]').click();
    }

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'retry');

    cy.get('[data-testid="retry-after"]')
      .should('be.visible')
      .and('match', /\d+/);
  });

  it('should disable submit button after rate limit exceeded', () => {
    for (let i = 0; i < 6; i++) {
      cy.get('input[name="email"]').clear().type(`disable${i}@test.com`);
      cy.get('button[type="submit"]').click();
    }

    cy.get('button[type="submit"]')
      .should('be.disabled')
      .and('have.attr', 'aria-disabled', 'true');
  });

  it('should allow form submission after rate limit window resets', () => {
    for (let i = 0; i < 6; i++) {
      cy.get('input[name="email"]').clear().type(`reset${i}@mail.com`);
      cy.get('button[type="submit"]').click();
    }

    cy.get('[data-testid="error-message"]').should('be.visible');

    cy.wait(61000);

    cy.get('input[name="email"]').clear().type('newuser@example.com');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'Success');
  });
});

