describe('Session Expired Error State', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/login');
    cy.get('input[name="email"]').type('testuser@example.com');
    cy.get('input[name="password"]').type('password123');
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');
  });

  it('should display session expired message when token times out', () => {
    cy.window().then((win) => {
      win.localStorage.setItem('authToken', 'expired_token');
      win.sessionStorage.setItem('tokenExpiry', Date.now() - 1000);
    });
    cy.intercept('GET', '/api/user/profile', {
      statusCode: 401,
      body: { message: 'Token expired' }
    }).as('expiredToken');
    cy.reload();
    cy.wait('@expiredToken');
    cy.get('[data-testid="session-expired-message"]').should('be.visible');
    cy.get('[data-testid="session-expired-message"]').should('contain', 'Your session has expired');
  });

  it('should show session expired modal with appropriate text', () => {
    cy.window().then((win) => {
      win.localStorage.removeItem('authToken');
    });
    cy.intercept('GET', '/api/**', { statusCode: 401 }).as('unauthorized');
    cy.get('button[data-testid="refresh-btn"]').click();
    cy.wait('@unauthorized');
    cy.get('[data-testid="expired-modal"]').should('be.visible');
    cy.get('[data-testid="expired-modal-title"]').should('contain', 'Session Expired');
    cy.get('[data-testid="expired-modal-message"]').should('contain', 'Please log in again');
  });

  it('should redirect to login page when dismissing session expired message', () => {
    cy.window().then((win) => {
      win.localStorage.removeItem('authToken');
    });
    cy.intercept('GET', '/api/**', { statusCode: 401 }).as('unauthorized');
    cy.get('button[data-testid="action-btn"]').click();
    cy.wait('@unauthorized');
    cy.get('[data-testid="expired-modal-close"]').click();
    cy.url().should('include', '/login');
  });

  it('should display session expired message on API call failure due to token expiry', () => {
    cy.intercept('POST', '/api/data/save', {
      statusCode: 401,
      body: { error: 'Unauthorized', message: 'Token has expired' }
    }).as('saveDataUnauthorized');
    cy.get('[data-testid="save-btn"]').click();
    cy.wait('@saveDataUnauthorized');
    cy.get('[data-testid="error-notification"]').should('be.visible');
    cy.get('[data-testid="error-notification"]').should('contain', 'session expired');
  });
});

