describe('Form Submission Error Auto-Scroll', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should scroll error messages into view on form submission', () => {
    cy.get('form').then(($form) => {
      const formHeight = $form.height();
      cy.window().then((win) => {
        cy.get('input[name="email"]').clear();
        cy.get('input[name="password"]').clear();
        cy.get('button[type="submit"]').click();
        cy.get('[data-testid="error-message"]').should('exist');
        cy.get('[data-testid="error-message"]').then(($error) => {
          const errorRect = $error[0].getBoundingClientRect();
          expect(errorRect.top).to.be.greaterThan(0);
          expect(errorRect.top).to.be.lessThan(win.innerHeight);
        });
      });
    });
  });

  it('should scroll multiple field errors into view', () => {
    cy.get('input[name="username"]').clear();
    cy.get('input[name="email"]').clear();
    cy.get('input[name="phone"]').clear();
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="error-message"]').first().should('be.visible');
    cy.get('[data-testid="error-message"]').first().then(($error) => {
      cy.window().then((win) => {
        const errorTop = $error[0].getBoundingClientRect().top;
        expect(errorTop).to.be.greaterThan(0);
        expect(errorTop).to.be.lessThan(win.innerHeight);
      });
    });
  });

  it('should scroll to first error when multiple errors exist', () => {
    cy.get('form').scrollTo(0, 500);
    cy.get('input[name="email"]').clear();
    cy.get('input[name="password"]').clear();
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="error-message"]').first().should('be.visible');
    cy.window().then((win) => {
      cy.get('[data-testid="error-message"]').first().then(($error) => {
        const scrollTop = win.scrollY;
        const errorTop = $error[0].getBoundingClientRect().top + scrollTop;
        expect(Math.abs(scrollTop - errorTop)).to.be.lessThan(100);
      });
    });
  });

  it('should not scroll when no errors present', () => {
    cy.window().then((win) => {
      const initialScroll = win.scrollY;
      cy.get('input[name="email"]').type('valid@example.com');
      cy.get('input[name="password"]').type('ValidPass123');
      cy.get('button[type="submit"]').click();
      cy.window().then((winAfter) => {
        expect(winAfter.scrollY).to.equal(initialScroll);
      });
    });
  });
});

