describe('Multiple Concurrent API Calls', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should resolve multiple concurrent API calls before displaying data', () => {
    cy.intercept('GET', '/api/users', { fixture: 'users.json' }).as('getUsers');
    cy.intercept('GET', '/api/posts', { fixture: 'posts.json' }).as('getPosts');
    cy.intercept('GET', '/api/comments', { fixture: 'comments.json' }).as('getComments');

    cy.get('[data-testid="load-data-btn"]').click();

    cy.wait(['@getUsers', '@getPosts', '@getComments']).then((interceptions) => {
      expect(interceptions[0].response.statusCode).to.equal(200);
