      req.reply((res) => {
        res.delay(1000);
      });
    }).as('delayedUsers');

    cy.get('[data-testid="load-data-btn"]').click();
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.wait('@delayedUsers');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });

  it('should handle errors in concurrent API calls gracefully', () => {
    cy.intercept('GET', '/api/users', { statusCode: 500, body: { error: 'Server error' } }).as('failedUsers');
    cy.intercept('GET', '/api/posts', { fixture: 'posts.json' }).as('getPosts');
    cy.intercept('GET', '/api/comments', { fixture: 'comments.json' }).as('getComments');

    cy.get('[data-testid="load-data-btn"]').click();

    cy.wait(['@failedUsers', '@getPosts', '@getComments']);
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load users');
  });
});

