import { test, expect } from '@playwright/test';

test.describe('Multiple Concurrent API Calls', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should resolve multiple concurrent API calls before displaying data', async ({ page }) => {
    const usersPromise = page.waitForResponse(response => response.url().includes('/api/users') && response.status() === 200);
    const postsPromise = page.waitForResponse(response => response.url().includes('/api/posts') && response.status() === 200);
    const commentsPromise = page.waitForResponse(response => response.url().includes('/api/comments') && response.status() === 200);

    await page.click('[data-testid="load-data-btn"]');

    const [usersRes, postsRes, commentsRes] = await Promise.all([usersPromise, postsPromise, commentsPromise]);

    expect(usersRes.status()).toBe(200);
    expect(postsRes.status()).toBe(200);
    expect(commentsRes.status()).toBe(200);

    await expect(page.locator('[data-testid="data-container"]')).toBeVisible();
    await expect(page.locator('[data-testid="user-list"]')).toContainText('User');
    await expect(page.locator('[data-testid="post-list"]')).toContainText('Post');
    await expect(page.locator('[data-testid="comment-list"]')).toContainText('Comment');
  });

  test('should display loading state while API calls are pending', async ({ page }) => {
    await page.route('**/api/users', async route => {
      await page.waitForTimeout(1000);
      await route.continue();
    });

    await page.click('[data-testid="load-data-btn"]');
    await expect(page.locator('[data-testid="loading-spinner"]')).toBeVisible();

    await page.waitForResponse(response => response.url().includes('/api/users'));
    await expect(page.locator('[data-testid="loading-spinner"]')).not.toBeVisible();
  });

  test('should handle errors in concurrent API calls gracefully', async ({ page }) => {
    await page.route('**/api/users', route => route.abort());

    const postsPromise = page.waitForResponse(response => response.url().includes('/api/posts'));
    const commentsPromise = page.waitForResponse(response => response.url().includes('/api/comments'));

    await page.click('[data-testid="load-data-btn"]');

    await Promise.all([postsPromise, commentsPromise]);

    await expect(page.locator('[data-testid="error-message"]')).toBeVisible();
    await expect(page.locator('[data-testid="error-message"]')).toContainText('Failed to load users');
  });

  test('should resolve all concurrent requests with proper data aggregation', async ({ page }) => {
    const responses = [];

    page.on('response', response => {
      if (response.url().includes('/api/')) {
        responses.push(response.status());
      }
    });

    await page.click('[data-testid="load-data-btn"]');

    await page.waitForSelector('[data-testid="data-container"][data-loaded="true"]');

    expect(responses.length).toBe(3);
    expect(responses.every(status => status === 200)).toBe(true);
  });
});

