describe('Lazy-loaded components smooth appearance without layout shift', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should load lazy components without causing layout shift', () => {
    cy.get('[data-testid="lazy-component"]').should('exist');

    const initialLayout = {};
    cy.window().then((win) => {
      const rect = win.document.querySelector('[data-testid="container"]').getBoundingClientRect();
      initialLayout.height = rect.height;
      initialLayout.width = rect.width;
    });

    cy.get('[data-testid="lazy-component"]').should('be.visible');
    cy.wait(1000);

    cy.window().then((win) => {
      const rect = win.document.querySelector('[data-testid="container"]').getBoundingClientRect();
      expect(rect.height).to.equal(initialLayout.height);
      expect(rect.width).to.equal(initialLayout.width);
    });
  });

  it('should fade in lazy components smoothly', () => {
    cy.get('[data-testid="lazy-component"]').should('have.css', 'opacity', '0');

    cy.get('[data-testid="lazy-component"]').should('have.css', 'transition');

    cy.get('[data-testid="lazy-component"]', { timeout: 5000 }).should('have.css', 'opacity', '1');
  });

  it('should maintain scroll position while lazy loading', () => {
    cy.scrollTo('bottom');
    cy.window().then((win) => {
      const scrollY = win.scrollY;
      cy.get('[data-testid="lazy-list-item"]').should('be.visible');
      cy.wait(1500);
      cy.window().then((win2) => {
        expect(win2.scrollY).to.equal(scrollY);
      });
    });
  });

  it('should render lazy components with proper spacing', () => {
    cy.get('[data-testid="lazy-component-1"]').should('be.visible');
    cy.get('[data-testid="lazy-component-2"]').should('be.visible');

    cy.get('[data-testid="lazy-component-1"]').then(($el1) => {
      cy.get('[data-testid="lazy-component-2"]').then(($el2) => {
        const rect1 = $el1[0].getBoundingClientRect();
        const rect2 = $el2[0].getBoundingClientRect();
        const spacing = rect2.top - rect1.bottom;
        expect(spacing).to.be.greaterThan(0);
      });
    });
  });
});

