import { test, expect, Page } from '@playwright/test';

test.describe('Lazy-loaded components smooth appearance without layout shift', () => {
  let page: Page;

  test.beforeEach(async ({ page: testPage }) => {
    page = testPage;
    await page.goto('http://localhost:3000');
  });

  test('should load lazy components without causing layout shift', async () => {
    await page.waitForSelector('[data-testid="lazy-component"]');

    const containerLocator = page.locator('[data-testid="container"]');
    const initialBBox = await containerLocator.boundingBox();

    await expect(page.locator('[data-testid="lazy-component"]')).toBeVisible();
    await page.waitForTimeout(1000);

    const finalBBox = await containerLocator.boundingBox();
    expect(finalBBox?.height).toBe(initialBBox?.height);
    expect(finalBBox?.width).toBe(initialBBox?.width);
  });

  test('should fade in lazy components smoothly', async () => {
    const lazyComponent = page.locator('[data-testid="lazy-component"]');

    const initialOpacity = await lazyComponent.evaluate((el) => window.getComputedStyle(el).opacity);
    expect(initialOpacity).toBe('0');

    const hasTransition = await lazyComponent.evaluate((el) => 
      window.getComputedStyle(el).transition.length > 0
    );
    expect(hasTransition).toBeTruthy();

    await page.waitForFunction(
      () => window.getComputedStyle(document.querySelector('[data-testid="lazy-component"]')!).opacity === '1',
      { timeout: 5000 }
    );

    const finalOpacity = await lazyComponent.evaluate((el) => window.getComputedStyle(el).opacity);
    expect(finalOpacity).toBe('1');
  });

  test('should maintain scroll position while lazy loading', async () => {
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
    const initialScrollY = await page.evaluate(() => window.scrollY);

    await expect(page.locator('[data-testid="lazy-list-item"]')).toBeVisible();
    await page.waitForTimeout(1500);

    const finalScrollY = await page.evaluate(() => window.scrollY);
    expect(finalScrollY).toBe(initialScrollY);
  });

  test('should render lazy components with proper spacing', async () => {
    await expect(page.locator('[data-testid="lazy-component-1"]')).toBeVisible();
    await expect(page.locator('[data-testid="lazy-component-2"]')).toBeVisible();

    const bbox1 = await page.locator('[data-testid="lazy-component-1"]').boundingBox();
    const bbox2 = await page.locator('[data-testid="lazy-component-2"]').boundingBox();

    const spacing = bbox2!.y - (bbox1!.y + bbox1!.height);
    expect(spacing).toBeGreaterThan(0);
  });

  test('should load multiple lazy components without cumulative layout shift', async () => {
    const layoutShifts: number[] = [];

    await page.on('framenavigated', async () => {
      const height = await page.evaluate(() => document.body.scrollHeight);
      layoutShifts.push(height);
    });

    await page.waitForSelector('[data-testid="lazy-component"]', { timeout: 5000 });

    const maxShift = layoutShifts.length > 1 
      ? Math.max(...layoutShifts.slice(1).map((h, i) => Math.abs(h - layoutShifts[i])))
      : 0;

    expect(maxShift).toBeLessThan(100);
  });
});

