describe('Debounced Search', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should trigger search only after 300ms of inactivity', () => {
    cy.get('[data-testid="search-input"]').as('searchInput');
    cy.get('[data-testid="search-results"]').as('results');

    // Type first character
    cy.get('@searchInput').type('a');
    cy.get('@results').should('not.exist');

    // Type second character within 300ms
    cy.get('@searchInput').type('b');
    cy.get('@results').should('not.exist');

    // Wait 300ms and verify search is triggered
    cy.wait(300);
    cy.get('@results').should('be.visible');
    cy.get('@results').should('contain', 'ab');
  });

  it('should reset debounce timer on each keystroke', () => {
    cy.get('[data-testid="search-input"]').as('searchInput');
    cy.get('[data-testid="search-results"]').as('results');

    cy.get('@searchInput').type('test');
    cy.wait(150);
    cy.get('@results').should('not.exist');

    // Type more within 300ms - should reset timer
    cy.get('@searchInput').type('ing');
    cy.wait(150);
    cy.get('@results').should('not.exist');

    // Now wait for debounce to complete
    cy.wait(300);
    cy.get('@results').should('be.visible');
    cy.get('@results').should('contain', 'testing');
  });

  it('should not trigger multiple searches during debounce window', () => {
    cy.get('[data-testid="search-input"]').as('searchInput');
    cy.get('[data-testid="search-call-count"]').as('callCount');

    cy.get('@callCount').should('have.text', '0');

    cy.get('@searchInput').type('a');
    cy.wait(100);
    cy.get('@searchInput').type('b');
    cy.wait(100);
    cy.get('@searchInput').type('c');

    // Wait for debounce
    cy.wait(300);
    cy.get('@callCount').should('have.text', '1');
  });

  it('should handle rapid sequential searches', () => {
    cy.get('[data-testid="search-input"]').as('searchInput');
    cy.get('[data-testid="search-results"]').as('results');

    // First search
    cy.get('@searchInput').type('query1');
    cy.wait(350);
    cy.get('@results').should('contain', 'query1');

    // Clear and second search
    cy.get('@searchInput').clear();
    cy.get('@searchInput').type('query2');
    cy.wait(350);
    cy.get('@results').should('contain', 'query2');
  });
});

