describe('Search Race Condition Handling', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/search');
  });

  it('should display only the latest search result when multiple requests are made', () => {
    const searchInput = 'input[data-testid="search-input"]';
    const resultsContainer = '[data-testid="search-results"]';

    cy.get(searchInput).type('first', { delay: 50 });
    cy.wait(100);
    cy.get(searchInput).clear();
    cy.get(searchInput).type('second', { delay: 50 });
    cy.wait(100);
    cy.get(searchInput).clear();
    cy.get(searchInput).type('latest', { delay: 50 });

    cy.get(resultsContainer).should('exist');
    cy.get(resultsContainer).should('contain', 'latest');
    cy.get(resultsContainer).should('not.contain', 'first');
    cy.get(resultsContainer).should('not.contain', 'second');
  });

  it('should abort previous search requests when new search is initiated', () => {
    cy.intercept('GET', '**/api/search*', (req) => {
      req.reply((res) => {
        res.delay(500);
      });
    }).as('searchRequest');

    const searchInput = 'input[data-testid="search-input"]';
    cy.get(searchInput).type('query1', { delay: 30 });
    cy.wait(50);
    cy.get(searchInput).clear();
    cy.get(searchInput).type('query2', { delay: 30 });

    cy.get('@searchRequest.all').then((interceptions) => {
      expect(interceptions.length).to.be.greaterThan(0);
    });
    cy.get('[data-testid="search-results"]').should('contain', 'query2');
  });

  it('should handle rapid consecutive searches correctly', () => {
    const searchInput = 'input[data-testid="search-input"]';
    const resultsContainer = '[data-testid="search-results"]';

    for (let i = 0; i < 5; i++) {
      cy.get(searchInput).clear();
      cy.get(searchInput).type(`search${i}`, { delay: 20 });
      cy.wait(30);
    }

    cy.get(resultsContainer).should('contain', 'search4');
    cy.get(resultsContainer).should('not.contain', 'search0');
    cy.get(resultsContainer).should('not.contain', 'search1');
  });
});

