describe('Countdown Timer Async/Await Tests', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display countdown timer that updates every second', () => {
    cy.get('[data-testid="countdown-timer"]').should('exist');
    cy.get('[data-testid="timer-display"]').should('contain', '10');

    cy.wait(1000);
    cy.get('[data-testid="timer-display"]').should('contain', '9');

    cy.wait(1000);
    cy.get('[data-testid="timer-display"]').should('contain', '8');
  });

  it('should start timer on button click', () => {
    cy.get('[data-testid="start-button"]').click();
    cy.get('[data-testid="timer-display"]').should('exist');

    cy.wait(1000);
    cy.get('[data-testid="timer-display"]').invoke('text').then((initialText) => {
      cy.wait(1000);
      cy.get('[data-testid="timer-display"]').invoke('text').should('not.equal', initialText);
    });
  });

  it('should countdown to zero and stop', () => {
    cy.get('[data-testid="countdown-input"]').clear().type('3');
    cy.get('[data-testid="start-button"]').click();

    cy.wait(3100);
    cy.get('[data-testid="timer-display"]').should('contain', '0');
    cy.get('[data-testid="status"]').should('contain', 'completed');
  });

  it('should update timer display with correct interval timing', () => {
    const timestamps = [];

    cy.get('[data-testid="start-button"]').click();
    cy.then(() => timestamps.push(Date.now()));

    cy.get('[data-testid="timer-display"]').should('contain', '5');
    cy.wait(1000).then(() => timestamps.push(Date.now()));

    cy.get('[data-testid="timer-display"]').should('contain', '4');
    cy.wait(1000).then(() => {
      const diff = timestamps[1] - timestamps[0];
      expect(diff).to.be.greaterThan(900);
      expect(diff).to.be.lessThan(1100);
    });
  });

  it('should pause and resume timer', () => {
    cy.get('[data-testid="start-button"]').click();
    cy.wait(500);
    cy.get('[data-testid="pause-button"]').click();

    cy.get('[data-testid="timer-display"]').invoke('text').then((pausedValue) => {
      cy.wait(1000);
      cy.get('[data-testid="timer-display"]').should('contain', pausedValue);
    });

    cy.get('[data-testid="resume-button"]').click();
    cy.wait(1000);
    cy.get('[data-testid="timer-display"]').invoke('text').should('not.contain', pausedValue);
  });
});

