    await startButton.click();

    await expect(timerDisplay).toContainText('5');
    const afterFirstSecond = Date.now();

    await page.waitForTimeout(1000);
    await expect(timerDisplay).toContainText('4');
    const afterSecondSecond = Date.now();

    const interval = afterSecondSecond - afterFirstSecond;
    expect(interval).toBeGreaterThan(900);
    expect(interval).toBeLessThan(1100);
  });

  test('should pause and resume timer', async ({ page }) => {
    const startButton = page.locator('[data-testid="start-button"]');
    const pauseButton = page.locator('[data-testid="pause-button"]');
    const resumeButton = page.locator('[data-testid="resume-button"]');
