  it('should update UI when receiving WebSocket message', () => {
    cy.window().then((win) => {
      const ws = new WebSocket('ws://localhost:8080');
      cy.wrap(ws).as('websocket');
    });

    cy.get('@websocket').then((ws) => {
      ws.send(JSON.stringify({ type: 'update', data: 'test message' }));
    });

    cy.get('[data-testid="message-container"]', { timeout: 5000 }).should('contain', 'test message');
  });

  it('should handle multiple real-time updates', () => {
    const messages = ['Update 1', 'Update 2', 'Update 3'];
    let messageIndex = 0;

    cy.window().then((win) => {
      const ws = new WebSocket('ws://localhost:8080');
      cy.wrap(ws).as('ws');

      ws.onopen = () => {
        messages.forEach((msg) => {
          ws.send(JSON.stringify({ type: 'message', content: msg }));
