import { test, expect } from '@playwright/test';

test.describe('WebSocket Real-time UI Updates', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should establish WebSocket connection on page load', async ({ page }) => {
    const wsPromise = page.waitForEvent('websocket');
    const ws = await wsPromise;
    expect(ws).toBeTruthy();
  });

  test('should update UI when receiving WebSocket message', async ({ page }) => {
    let wsConnection;
    page.on('websocket', (ws) => {
      wsConnection = ws;
    });

    await page.waitForTimeout(1000);

    const messagePromise = page.waitForEvent('framenavigated');
    await page.evaluate(() => {
      const ws = new WebSocket('ws://localhost:8080');
      ws.onopen = () => {
        ws.send(JSON.stringify({ type: 'update', data: 'test message' }));
      };
    });

    const messageElement = page.locator('[data-testid="message-container"]');
    await expect(messageElement).toContainText('test message', { timeout: 5000 });
  });

  test('should handle multiple real-time updates', async ({ page }) => {
    const messages = ['Update 1', 'Update 2', 'Update 3'];

    await page.evaluate((msgs) => {
      const ws = new WebSocket('ws://localhost:8080');
      ws.onopen = () => {
        msgs.forEach((msg) => {
          ws.send(JSON.stringify({ type: 'message', content: msg }));
        });
      };
    }, messages);

    const updateElement = page.locator('[data-testid="ui-update"]');
    for (const msg of messages) {
      await expect(updateElement).toContainText(msg, { timeout: 5000 });
    }
  });

  test('should reconnect on WebSocket disconnection', async ({ page }) => {
    await page.evaluate(() => {
      const ws = new WebSocket('ws://localhost:8080');
      setTimeout(() => {
        ws.close();
      }, 500);
    });

    const statusElement = page.locator('[data-testid="connection-status"]');
    await expect(statusElement).toContainText('Connected', { timeout: 10000 });
  });

  test('should display loading state while waiting for WebSocket data', async ({ page }) => {
    const loadingIndicator = page.locator('[data-testid="loading-indicator"]');
    await expect(loadingIndicator).toBeVisible();

    await page.evaluate(() => {
      const ws = new WebSocket('ws://localhost:8080');
      ws.onopen = () => {
        ws.send(JSON.stringify({ type: 'init' }));
      };
    });

    await expect(loadingIndicator).not.toBeVisible({ timeout: 5000 });
    const content = page.locator('[data-testid="content"]');
    await expect(content).toBeVisible();
  });

  test('should handle WebSocket errors gracefully', async ({ page }) => {
    await page.evaluate(() => {
      new WebSocket('ws://invalid-url:8080');
    });

    const errorMessage = page.locator('[data-testid="error-message"]');
    await expect(errorMessage).toBeVisible({ timeout: 5000 });
  });
});

