describe('Async Error Retry Option', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display retry option when async error occurs', () => {
    cy.intercept('GET', '/api/data', { statusCode: 500, body: { error: 'Server error' } }).as('failedRequest');
    cy.get('[data-cy=fetch-button]').click();
    cy.wait('@failedRequest');
    cy.get('[data-cy=error-message]').should('be.visible');
    cy.get('[data-cy=retry-button]').should('be.visible').and('contain', 'Retry');
  });

  it('should retry async operation when retry button is clicked', () => {
    cy.intercept('GET', '/api/data', { statusCode: 500, body: { error: 'Server error' } }, { times: 1 }).as('failedRequest');
    cy.intercept('GET', '/api/data', { statusCode: 200, body: { success: true, data: 'test' } }).as('successRequest');
    cy.get('[data-cy=fetch-button]').click();
    cy.wait('@failedRequest');
    cy.get('[data-cy=retry-button]').click();
    cy.wait('@successRequest');
    cy.get('[data-cy=success-message]').should('be.visible').and('contain', 'test');
    cy.get('[data-cy=error-message]').should('not.exist');
  });

  it('should display error after max retries exceeded', () => {
    cy.intercept('GET', '/api/data', { statusCode: 500, body: { error: 'Server error' } }).as('failedRequest');
    cy.get('[data-cy=fetch-button]').click();
    cy.wait('@failedRequest');
    cy.get('[data-cy=retry-button]').click();
    cy.wait('@failedRequest');
    cy.get('[data-cy=retry-button]').click();
    cy.wait('@failedRequest');
    cy.get('[data-cy=error-message]').should('contain', 'Max retries exceeded');
    cy.get('[data-cy=retry-button]').should('be.disabled');
  });

  it('should clear retry option when new request is initiated', () => {
    cy.intercept('GET', '/api/data', { statusCode: 500 }).as('failedRequest');
    cy.get('[data-cy=fetch-button]').click();
    cy.wait('@failedRequest');
    cy.get('[data-cy=retry-button]').should('be.visible');
    cy.get('[data-cy=fetch-button]').click();
    cy.get('[data-cy=loading-spinner]').should('be.visible');
    cy.get('[data-cy=retry-button]').should('not.be.visible');
  });
});

