describe('Long-running task persistence across page refreshes', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should persist task progress after page refresh', () => {
    cy.get('[data-testid="start-task-button"]').click();
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');
    cy.get('[data-testid="task-progress"]').invoke('text').then((initialProgress) => {
      cy.wait(1000);
      cy.reload();
      cy.get('[data-testid="task-status"]').should('contain', 'In Progress');
      cy.get('[data-testid="task-progress"]').invoke('text').then((refreshedProgress) => {
        expect(parseInt(refreshedProgress)).to.be.at.least(parseInt(initialProgress));
      });
    });
  });

  it('should complete task after multiple page refreshes', () => {
    cy.get('[data-testid="start-task-button"]').click();
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');
    cy.reload();
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');
    cy.reload();
    cy.get('[data-testid="task-status"]', { timeout: 15000 }).should('contain', 'Completed');
    cy.get('[data-testid="task-result"]').should('be.visible');
  });

  it('should restore task data from local storage on refresh', () => {
    cy.get('[data-testid="start-task-button"]').click();
    cy.window().then((win) => {
      const taskData = JSON.parse(win.localStorage.getItem('currentTask'));
      expect(taskData).to.have.property('id');
      expect(taskData).to.have.property('progress');
    });
    cy.reload();
    cy.window().then((win) => {
      const restoredData = JSON.parse(win.localStorage.getItem('currentTask'));
      expect(restoredData).to.have.property('id');
      expect(restoredData).to.have.property('progress');
    });
  });

  it('should cancel long-running task and clear persistence', () => {
    cy.get('[data-testid="start-task-button"]').click();
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');
    cy.get('[data-testid="cancel-task-button"]').click();
    cy.get('[data-testid="task-status"]').should('contain', 'Cancelled');
    cy.window().then((win) => {
      expect(win.localStorage.getItem('currentTask')).to.be.null;
    });
    cy.reload();
    cy.get('[data-testid="task-status"]').should('not.exist');
  });
});

