describe('Async State Preservation During Navigation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should preserve async state when navigating to another page', () => {
    cy.get('[data-testid="async-data-button"]').click();
    cy.get('[data-testid="loading-indicator"]').should('be.visible');

    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: { data: 'test-value', timestamp: Date.now() }
    }).as('fetchData');

    cy.wait('@fetchData');
    cy.get('[data-testid="async-result"]').should('contain', 'test-value');

    cy.get('[data-testid="navigate-link"]').click();
    cy.url().should('include', '/page2');

    cy.go('back');
    cy.url().should('include', '/');
    cy.get('[data-testid="async-result"]').should('contain', 'test-value');
  });

  it('should maintain async state across multiple navigations', () => {
    cy.get('[data-testid="async-form"]').within(() => {
      cy.get('[data-testid="input-field"]').type('test-input');
      cy.get('[data-testid="submit-button"]').click();
    });

    cy.get('[data-testid="form-status"]').should('contain', 'Processing');

    cy.intercept('POST', '/api/submit', {
      statusCode: 200,
      body: { success: true, id: '12345' }
    }).as('submitForm');

    cy.wait('@submitForm');
    cy.get('[data-testid="form-status"]').should('contain', 'Success');
    cy.get('[data-testid="submission-id"]').should('contain', '12345');

    cy.get('[data-testid="next-page-link"]').click();
    cy.go('back');

    cy.get('[data-testid="submission-id"]').should('contain', '12345');
    cy.get('[data-testid="form-status"]').should('contain', 'Success');
  });

  it('should handle async state timeout during navigation', () => {
    cy.get('[data-testid="slow-async-button"]').click();
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    cy.intercept('GET', '/api/slow-data', (req) => {
      req.reply((res) => {
        setTimeout(() => res.send({ statusCode: 200, body: { data: 'slow-data' } }), 2000);
      });
    }).as('slowFetch');

    cy.get('[data-testid="navigate-link"]').click();
    cy.url().should('include', '/page2');

    cy.go('back');
    cy.wait('@slowFetch', { timeout: 5000 });
    cy.get('[data-testid="async-result"]').should('contain', 'slow-data');
  });
});

