describe('Modal Focus Trap', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should trap focus inside modal when opened', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.focused().should('have.attr', 'data-testid').and('include', 'modal');
  });

  it('should keep focus within modal when tabbing', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="modal-first-focusable"]').focus();
    cy.focused().should('have.attr', 'data-testid', 'modal-first-focusable');

    cy.realPress('Tab');
    cy.focused().should('have.attr', 'data-testid').and('not.equal', 'outside-element');
  });

  it('should return focus to trigger element after modal closes', () => {
    cy.get('[data-testid="open-modal-btn"]').focus();
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="close-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('not.be.visible');
    cy.focused().should('have.attr', 'data-testid', 'open-modal-btn');
  });

  it('should prevent focus from escaping to background elements', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="background-button"]').should('not.have.focus');
    cy.get('[data-testid="background-button"]').click({ force: true });
    cy.get('[data-testid="modal"]').should('be.visible');
  });

  it('should trap focus on shift+tab at first element', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-last-focusable"]').focus();

    cy.realPress(['Shift', 'Tab']);
    cy.focused().should('not.have.attr', 'data-testid', 'background-button');
  });
});

