import { test, expect } from '@playwright/test';

test.describe('Modal Focus Trap', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should trap focus inside modal when opened', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    const modal = page.locator('[data-testid="modal"]');
    await expect(modal).toBeVisible();

    const focusedElement = await page.evaluate(() => document.activeElement?.getAttribute('data-testid'));
    expect(focusedElement).toContain('modal');
  });

  test('should keep focus within modal when tabbing', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    await expect(page.locator('[data-testid="modal"]')).toBeVisible();

    await page.focus('[data-testid="modal-first-focusable"]');
    let focusedElement = await page.evaluate(() => document.activeElement?.getAttribute('data-testid'));
    expect(focusedElement).toBe('modal-first-focusable');

    await page.keyboard.press('Tab');
    focusedElement = await page.evaluate(() => document.activeElement?.getAttribute('data-testid'));
    expect(focusedElement).not.toBe('outside-element');
  });

  test('should return focus to trigger element after modal closes', async ({ page }) => {
    const openBtn = page.locator('[data-testid="open-modal-btn"]');
    await openBtn.focus();
    await openBtn.click();
    await expect(page.locator('[data-testid="modal"]')).toBeVisible();

