    await expect(page.locator('[data-testid="modal"]')).not.toBeVisible();

    const focusedElement = await page.evaluate(() => document.activeElement?.getAttribute('data-testid'));
    expect(focusedElement).toBe('open-modal-btn');
  });

  test('should prevent focus from escaping to background elements', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    await expect(page.locator('[data-testid="modal"]')).toBeVisible();

    const bgButton = page.locator('[data-testid="background-button"]');
    const isFocused = await bgButton.evaluate((el) => el === document.activeElement);
    expect(isFocused).toBe(false);

    await page.locator('[data-testid="background-button"]').click({ force: true });
    await expect(page.locator('[data-testid="modal"]')).toBeVisible();
  });

  test('should trap focus on shift+tab at first element', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    await page.focus('[data-testid="modal-last-focusable"]');

    await page.keyboard.press('Shift+Tab');
    const focusedElement = await page.evaluate(() => document.activeElement?.getAttribute('data-testid'));
    expect(focusedElement).not.toBe('background-button');
  });
});

