    cy.get('[data-testid="modal"]').then($modal => {
      const initialTop = $modal.position().top;
      cy.get('[data-testid="modal-content"]').scrollTo('bottom');
      cy.get('[data-testid="modal"]').then($modalAfter => {
        expect($modalAfter.position().top).to.equal(initialTop);
      });
    });
