import { test, expect } from '@playwright/test';

test.describe('Modal Independent Scrolling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should allow modal content to scroll independently when overflow occurs', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    const modal = page.locator('[data-testid="modal"]');
    await expect(modal).toBeVisible();
    const modalContent = page.locator('[data-testid="modal-content"]');
    const overflowValue = await modalContent.evaluate(el => window.getComputedStyle(el).overflowY);
    expect(overflowValue).toBe('auto');
  });

  test('should maintain modal position while scrolling content', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    const modal = page.locator('[data-testid="modal"]');
    const initialBox = await modal.boundingBox();
    const modalContent = page.locator('[data-testid="modal-content"]');
    await modalContent.evaluate(el => {
      el.scrollTop = el.scrollHeight;
    });
    const finalBox = await modal.boundingBox();
    expect(initialBox.y).toBe(finalBox.y);
  });

  test('should scroll modal content independently from page scroll', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    const modalContent = page.locator('[data-testid="modal-content"]');
    await modalContent.evaluate(el => {
      el.scrollTop = el.scrollHeight;
    });
    const pageScroll = await page.evaluate(() => window.scrollY);
    expect(pageScroll).toBe(0);
  });

  test('should display scrollbar when modal content overflows', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    const modalContent = page.locator('[data-testid="modal-content"]');
    const scrollHeight = await modalContent.evaluate(el => el.scrollHeight);
    const clientHeight = await modalContent.evaluate(el => el.clientHeight);
    expect(scrollHeight).toBeGreaterThan(clientHeight);
  });

  test('should allow keyboard scrolling within modal', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    const modalContent = page.locator('[data-testid="modal-content"]');
    await modalContent.focus();
    await page.keyboard.press('PageDown');
    const scrollTop = await modalContent.evaluate(el => el.scrollTop);
    expect(scrollTop).toBeGreaterThan(0);
  });

  test('should handle touch scrolling on modal content', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    const modalContent = page.locator('[data-testid="modal-content"]');
    await modalContent.evaluate(el => {
      el.scrollTop = Math.floor(el.scrollHeight * 0.25);
    });
    const scrollTop = await modalContent.evaluate(el => el.scrollTop);
    expect(scrollTop).toBeGreaterThan(0);
  });

  test('should not prevent external content from being accessible', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    const modal = page.locator('[data-testid="modal"]');
    await expect(modal).toBeVisible();
    const backdrop = page.locator('[data-testid="modal-backdrop"]');
    await expect(backdrop).toBeVisible();
  });
});

