import { test, expect } from '@playwright/test';

test.describe('Modal - Page Scroll Lock', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should prevent page scroll when modal is open', async ({ page }) => {
    await page.click('[data-testid="open-modal-button"]');
    await expect(page.locator('[data-testid="modal"]')).toBeVisible();

    const bodyOverflow = await page.locator('body').evaluate(el => 
      window.getComputedStyle(el).overflow
    );
    expect(bodyOverflow).toBe('hidden');
  });

  test('should restore scroll when modal is closed', async ({ page }) => {
    await page.click('[data-testid="open-modal-button"]');
    await expect(page.locator('[data-testid="modal"]')).toBeVisible();

    let bodyOverflow = await page.locator('body').evaluate(el => 
      window.getComputedStyle(el).overflow
    );
    expect(bodyOverflow).toBe('hidden');

    await page.click('[data-testid="close-modal-button"]');
    await expect(page.locator('[data-testid="modal"]')).not.toBeVisible();

    bodyOverflow = await page.locator('body').evaluate(el => 
      window.getComputedStyle(el).overflow
    );
    expect(bodyOverflow).not.toBe('hidden');
  });

  test('should prevent scrolling with wheel event when modal is open', async ({ page }) => {
    await page.click('[data-testid="open-modal-button"]');
    await expect(page.locator('[data-testid="modal"]')).toBeVisible();

    const scrollBefore = await page.evaluate(() => window.scrollY);
    await page.locator('body').dispatchEvent('wheel', { deltaY: 100 });
    const scrollAfter = await page.evaluate(() => window.scrollY);

    expect(scrollAfter).toBe(scrollBefore);
  });

  test('should allow scroll on modal content when modal is open', async ({ page }) => {
    await page.click('[data-testid="open-modal-button"]');
    await expect(page.locator('[data-testid="modal-content"]')).toBeVisible();

