test.describe('Popover Toggle on Button Click', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display popover when button is clicked', async ({ page }) => {
    await page.click('[data-testid="popover-button"]');
    await expect(page.locator('[data-testid="popover-content"]')).toBeVisible();
  });

  test('should hide popover when button is clicked again', async ({ page }) => {
    const button = page.locator('[data-testid="popover-button"]');
    const popover = page.locator('[data-testid="popover-content"]');

    await button.click();
    await expect(popover).toBeVisible();
    await button.click();
    await expect(popover).not.toBeVisible();
  });

  test('should toggle popover multiple times', async ({ page }) => {
    const button = page.locator('[data-testid="popover-button"]');
    const popover = page.locator('[data-testid="popover-content"]');

    await button.click();
    await expect(popover).toBeVisible();
    await button.click();
    await expect(popover).not.toBeVisible();
    await button.click();
    await expect(popover).toBeVisible();
  });

  test('should close popover when clicking outside', async ({ page }) => {
    const button = page.locator('[data-testid="popover-button"]');
    const popover = page.locator('[data-testid="popover-content"]');

    await button.click();
    await expect(popover).toBeVisible();
    await page.click('body');
    await expect(popover).not.toBeVisible();
  });

  test('should have correct popover content', async ({ page }) => {
    await page.click('[data-testid="popover-button"]');
    await expect(page.locator('[data-testid="popover-content"]')).toContainText('Popover content');
  });
});

