describe('Modal Video Pause on Close', () => {
  beforeEach(() => {
    cy.visit('/')
  })

  it('should pause video when modal is closed', () => {
    cy.get('[data-testid="open-modal-btn"]').click()
    cy.get('[data-testid="modal"]').should('be.visible')
    cy.get('[data-testid="video"]').should('exist')
    cy.get('[data-testid="video"]').then(($video) => {
      expect($video[0].paused).to.equal(false)
    })
    cy.get('[data-testid="video"]').click()
    cy.get('[data-testid="video"]').then(($video) => {
      expect($video[0].paused).to.equal(true)
    })
    cy.get('[data-testid="close-modal-btn"]').click()
    cy.get('[data-testid="modal"]').should('not.be.visible')
    cy.get('[data-testid="video"]').then(($video) => {
      expect($video[0].paused).to.equal(true)
    })
  })

  it('should pause video when close icon is clicked', () => {
    cy.get('[data-testid="open-modal-btn"]').click()
    cy.get('[data-testid="modal"]').should('be.visible')
    cy.get('[data-testid="video"]').should('exist')
    cy.get('[data-testid="close-icon"]').click()
    cy.get('[data-testid="modal"]').should('not.be.visible')
    cy.get('[data-testid="video"]').then(($video) => {
      expect($video[0].paused).to.equal(true)
    })
  })

  it('should pause video when pressing escape key', () => {
    cy.get('[data-testid="open-modal-btn"]').click()
    cy.get('[data-testid="modal"]').should('be.visible')
    cy.get('body').type('{esc}')
    cy.get('[data-testid="modal"]').should('not.be.visible')
    cy.get('[data-testid="video"]').then(($video) => {
      expect($video[0].paused).to.equal(true)
    })
  })
})

