import { test, expect } from '@playwright/test';

test.describe('Modal Video Pause on Close', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/')
  })

  test('should pause video when modal is closed', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]')
    await expect(page.locator('[data-testid="modal"]')).toBeVisible()
    const video = page.locator('[data-testid="video"]')
    await expect(video).toBeTruthy()
    let isPaused = await video.evaluate((el) => (el as HTMLVideoElement).paused)
    expect(isPaused).toBe(false)
    await video.click()
    isPaused = await video.evaluate((el) => (el as HTMLVideoElement).paused)
    expect(isPaused).toBe(true)
    await page.click('[data-testid="close-modal-btn"]')
    await expect(page.locator('[data-testid="modal"]')).not.toBeVisible()
    isPaused = await video.evaluate((el) => (el as HTMLVideoElement).paused)
    expect(isPaused).toBe(true)
  })

  test('should pause video when close icon is clicked', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]')
    await expect(page.locator('[data-testid="modal"]')).toBeVisible()
    const video = page.locator('[data-testid="video"]')
    await expect(video).toBeTruthy()
    await page.click('[data-testid="close-icon"]')
    await expect(page.locator('[data-testid="modal"]')).not.toBeVisible()
    const isPaused = await video.evaluate((el) => (el as HTMLVideoElement).paused)
    expect(isPaused).toBe(true)
  })

  test('should pause video when pressing escape key', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]')
    await expect(page.locator('[data-testid="modal"]')).toBeVisible()
    const video = page.locator('[data-testid="video"]')
    await page.press('body', 'Escape')
    await expect(page.locator('[data-testid="modal"]')).not.toBeVisible()
    const isPaused = await video.evaluate((el) => (el as HTMLVideoElement).paused)
    expect(isPaused).toBe(true)
  })
})

