describe('Modal Focus Management', () => {
  beforeEach(() => {
    cy.visit('/')
  })

  it('should return focus to trigger button when modal closes', () => {
    cy.get('[data-testid="modal-trigger"]').as('triggerButton')
    cy.get('@triggerButton').click()
    cy.get('[data-testid="modal"]').should('be.visible')
    cy.get('[data-testid="modal-close-button"]').click()
    cy.get('[data-testid="modal"]').should('not.be.visible')
    cy.get('@triggerButton').should('have.focus')
  })

  it('should return focus to trigger button when clicking backdrop', () => {
    cy.get('[data-testid="modal-trigger"]').click()
    cy.get('[data-testid="modal"]').should('be.visible')
    cy.get('[data-testid="modal-backdrop"]').click({ force: true })
    cy.get('[data-testid="modal"]').should('not.be.visible')
    cy.get('[data-testid="modal-trigger"]').should('have.focus')
  })

  it('should return focus to trigger button when pressing Escape key', () => {
    cy.get('[data-testid="modal-trigger"]').click()
    cy.get('[data-testid="modal"]').should('be.visible')
    cy.get('body').type('{esc}')
    cy.get('[data-testid="modal"]').should('not.be.visible')
    cy.get('[data-testid="modal-trigger"]').should('have.focus')
  })

  it('should trap focus within modal while open', () => {
    cy.get('[data-testid="modal-trigger"]').click()
    cy.get('[data-testid="modal"]').should('be.visible')
    cy.get('[data-testid="modal-confirm-button"]').should('have.focus').or.be.focused
    cy.focused().should('not.be.null')
  })
})

