    cy.visit('/')
  })

  it('should open lightbox when clicking gallery image', () => {
    cy.get('[data-testid="gallery-image"]').first().click()
    cy.get('[data-testid="lightbox"]').should('be.visible')
  })

  it('should display correct image in lightbox', () => {
    const imageIndex = 0
    cy.get('[data-testid="gallery-image"]').eq(imageIndex).click()
    cy.get('[data-testid="lightbox-image"]').should('have.attr', 'src', '[data-testid="gallery-image"]').eq(imageIndex).should('have.attr', 'src')
  })

  it('should close lightbox when clicking close button', () => {
    cy.get('[data-testid="gallery-image"]').first().click()
    cy.get('[data-testid="lightbox"]').should('be.visible')
    cy.get('[data-testid="lightbox-close"]').click()
