  })

  it('should close lightbox when clicking overlay', () => {
    cy.get('[data-testid="gallery-image"]').first().click()
    cy.get('[data-testid="lightbox-overlay"]').click({ force: true })
    cy.get('[data-testid="lightbox"]').should('not.be.visible')
  })

  it('should navigate to next image in lightbox', () => {
    cy.get('[data-testid="gallery-image"]').first().click()
    cy.get('[data-testid="lightbox-next"]').click()
    cy.get('[data-testid="lightbox-image"]').should('be.visible')
