describe('Modal with Tabbed Content - Remember Active Tab', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should remember the active tab when modal is closed and reopened', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="tab-2"]').click();
    cy.get('[data-testid="tab-2"]').should('have.class', 'active');
    cy.get('[data-testid="tab-content-2"]').should('be.visible');

    cy.get('[data-testid="close-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('not.be.visible');

    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
    cy.get('[data-testid="tab-2"]').should('have.class', 'active');
    cy.get('[data-testid="tab-content-2"]').should('be.visible');
  });

  it('should switch between tabs and maintain state', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('[data-testid="tab-1"]').should('have.class', 'active');
    cy.get('[data-testid="tab-3"]').click();
    cy.get('[data-testid="tab-3"]').should('have.class', 'active');
    cy.get('[data-testid="tab-1"]').should('not.have.class', 'active');

    cy.get('[data-testid="close-modal-btn"]').click();
    cy.get('[data-testid="open-modal-btn"]').click();

    cy.get('[data-testid="tab-3"]').should('have.class', 'active');
  });

  it('should persist tab state in localStorage', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="tab-2"]').click();

    cy.window().then((win) => {
      const activeTab = win.localStorage.getItem('activeModalTab');
      expect(activeTab).to.equal('tab-2');
    });
  });

  it('should reset to first tab on page refresh if not persisted', () => {
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="tab-2"]').click();
    cy.reload();
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="tab-2"]').should('have.class', 'active');
  });
});

