import { test, expect } from '@playwright/test';

test.describe('Modal with Tabbed Content - Remember Active Tab', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should remember the active tab when modal is closed and reopened', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    await expect(page.locator('[data-testid="modal"]')).toBeVisible();

    await page.click('[data-testid="tab-2"]');
    await expect(page.locator('[data-testid="tab-2"]')).toHaveClass(/active/);
    await expect(page.locator('[data-testid="tab-content-2"]')).toBeVisible();

    await page.click('[data-testid="close-modal-btn"]');
    await expect(page.locator('[data-testid="modal"]')).not.toBeVisible();

    await page.click('[data-testid="open-modal-btn"]');
    await expect(page.locator('[data-testid="modal"]')).toBeVisible();
    await expect(page.locator('[data-testid="tab-2"]')).toHaveClass(/active/);
    await expect(page.locator('[data-testid="tab-content-2"]')).toBeVisible();
  });

  test('should switch between tabs and maintain state', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    await expect(page.locator('[data-testid="modal"]')).toBeVisible();

    await expect(page.locator('[data-testid="tab-1"]')).toHaveClass(/active/);
    await page.click('[data-testid="tab-3"]');
    await expect(page.locator('[data-testid="tab-3"]')).toHaveClass(/active/);
    await expect(page.locator('[data-testid="tab-1"]')).not.toHaveClass(/active/);

    await page.click('[data-testid="close-modal-btn"]');
    await page.click('[data-testid="open-modal-btn"]');

    await expect(page.locator('[data-testid="tab-3"]')).toHaveClass(/active/);
  });

  test('should persist tab state in localStorage', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    await page.click('[data-testid="tab-2"]');

    const activeTab = await page.evaluate(() => localStorage.getItem('activeModalTab'));
    expect(activeTab).toBe('tab-2');
  });

  test('should reset to first tab on page refresh if not persisted', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');
    await page.click('[data-testid="tab-2"]');
    await page.reload();
    await page.click('[data-testid="open-modal-btn"]');
    await expect(page.locator('[data-testid="tab-2"]')).toHaveClass(/active/);
  });

  test('should handle rapid tab switching', async ({ page }) => {
    await page.click('[data-testid="open-modal-btn"]');

    await page.click('[data-testid="tab-1"]');
    await page.click('[data-testid="tab-2"]');
    await page.click('[data-testid="tab-3"]');
    await page.click('[data-testid="tab-1"]');

    await expect(page.locator('[data-testid="tab-1"]')).toHaveClass(/active/);

    await page.click('[data-testid="close-modal-btn"]');
    await page.click('[data-testid="open-modal-btn"]');

    await expect(page.locator('[data-testid="tab-1"]')).toHaveClass(/active/);
  });
});

