describe('Onboarding Tour Modal', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display onboarding modal on page load', () => {
    cy.get('[data-testid="onboarding-modal"]').should('be.visible');
  });

  it('should display first step of tour', () => {
    cy.get('[data-testid="tour-step"]').should('contain', 'Step 1');
    cy.get('[data-testid="tour-content"]').should('be.visible');
  });

  it('should advance to next step when next button is clicked', () => {
    cy.get('[data-testid="tour-step"]').should('contain', 'Step 1');
    cy.get('[data-testid="tour-next-btn"]').click();
    cy.get('[data-testid="tour-step"]').should('contain', 'Step 2');
  });

  it('should go back to previous step when back button is clicked', () => {
    cy.get('[data-testid="tour-next-btn"]').click();
    cy.get('[data-testid="tour-step"]').should('contain', 'Step 2');
    cy.get('[data-testid="tour-back-btn"]').click();
    cy.get('[data-testid="tour-step"]').should('contain', 'Step 1');
  });

  it('should display all steps sequentially', () => {
    const steps = ['Step 1', 'Step 2', 'Step 3'];
    steps.forEach((step, index) => {
      if (index > 0) {
        cy.get('[data-testid="tour-next-btn"]').click();
