import { test, expect } from '@playwright/test';

test.describe('Table Filter by Search Input', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display all table rows on initial load', async ({ page }) => {
    const rows = page.locator('table tbody tr');
    await expect(rows).toHaveCount(await rows.count());
    expect(await rows.count()).toBeGreaterThan(0);
  });

  test('should filter table rows when typing in search input', async ({ page }) => {
    await page.fill('input[placeholder="Search"]', 'John');
    const rows = page.locator('table tbody tr');
    const rowCount = await rows.count();
    for (let i = 0; i < rowCount; i++) {
      const rowText = await rows.nth(i).textContent();
      expect(rowText).toContain('John');
    }
  });

  test('should show no results when search matches no rows', async ({ page }) => {
    await page.fill('input[placeholder="Search"]', 'NonexistentValue12345');
    const rows = page.locator('table tbody tr');
    await expect(rows).toHaveCount(0);
  });

  test('should update filter results as user types', async ({ page }) => {
    const searchInput = page.locator('input[placeholder="Search"]');
    const rows = page.locator('table tbody tr');
    await searchInput.type('J');
    const lengthAfterJ = await rows.count();
    await searchInput.type('oh');
    const lengthAfterJoh = await rows.count();
    expect(lengthAfterJoh).toBeLessThanOrEqual(lengthAfterJ);
  });

  test('should restore all rows when search input is cleared', async ({ page }) => {
    const searchInput = page.locator('input[placeholder="Search"]');
    const rows = page.locator('table tbody tr');
    const initialCount = await rows.count();
    await searchInput.fill('test');
    const filteredCount = await rows.count();
    expect(filteredCount).toBeLessThan(initialCount);
    await searchInput.clear();
    await expect(rows).toHaveCount(initialCount);
  });

  test('should perform case-insensitive search', async ({ page }) => {
    const searchInput = page.locator('input[placeholder="Search"]');
    const rows = page.locator('table tbody tr');
    await searchInput.fill('john');
    let rowCount = await rows.count();
    expect(rowCount).toBeGreaterThan(0);
    await searchInput.clear();
    await searchInput.fill('JOHN');
    rowCount = await rows.count();
    expect(rowCount).toBeGreaterThan(0);
  });
});

