describe('Table Loading State', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/table');
  });

  it('should display loading state while data is fetching', () => {
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(2000);
      });
    }).as('fetchData');

    cy.get('[data-testid="table-container"]').should('exist');
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-text"]').should('contain', 'Loading...');
    cy.get('[data-testid="table-body"]').should('not.exist');

    cy.wait('@fetchData');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="table-body"]').should('be.visible');
  });

  it('should hide loading state after data loads', () => {
    cy.intercept('GET', '/api/data', { fixture: 'table-data.json' }).as('fetchData');
    cy.wait('@fetchData');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);
  });

  it('should show loading skeleton or placeholder during fetch', () => {
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(1500);
      });
    });

    cy.get('[data-testid="loading-skeleton"]').should('be.visible');
    cy.get('[data-testid="loading-skeleton"]').should('have.css', 'opacity', '1');
  });
});

