import { test, expect } from '@playwright/test';

test.describe('Table Loading State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/table');
  });

  test('should display loading state while data is fetching', async ({ page }) => {
    await page.route('**/api/data', (route) => {
      setTimeout(() => route.continue(), 2000);
    });

    const tableContainer = page.locator('[data-testid="table-container"]');
    await expect(tableContainer).toBeVisible();

    const loadingSpinner = page.locator('[data-testid="loading-spinner"]');
    await expect(loadingSpinner).toBeVisible();

    const loadingText = page.locator('[data-testid="loading-text"]');
    await expect(loadingText).toContainText('Loading...');

    const tableBody = page.locator('[data-testid="table-body"]');
    await expect(tableBody).not.toBeVisible();

    await page.waitForLoadState('networkidle');
    await expect(loadingSpinner).not.toBeVisible();
    await expect(tableBody).toBeVisible();
  });

  test('should hide loading state after data loads', async ({ page }) => {
    await page.route('**/api/data', (route) => {
      route.continue();
    });

    await page.waitForLoadState('networkidle');
    const loadingSpinner = page.locator('[data-testid="loading-spinner"]');
    await expect(loadingSpinner).not.toBeVisible();

    const tableRows = page.locator('[data-testid="table-row"]');
    await expect(tableRows.first()).toBeVisible();
  });

  test('should show loading skeleton or placeholder during fetch', async ({ page }) => {
    await page.route('**/api/data', (route) => {
      setTimeout(() => route.continue(), 1500);
    });

    const loadingSkeleton = page.locator('[data-testid="loading-skeleton"]');
    await expect(loadingSkeleton).toBeVisible();
    const opacity = await loadingSkeleton.evaluate((el) => window.getComputedStyle(el).opacity);
    expect(parseFloat(opacity)).toBe(1);
  });
});

