import { test, expect } from '@playwright/test';

test.describe('Copy cell value by double-clicking', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should copy cell value to clipboard when double-clicked', async ({ page, context }) => {
    const targetCell = page.locator('table tbody tr:first-child td:first-child');
    const cellValue = await targetCell.textContent();
    await targetCell.dblclick();
    const clipboardText = await context.tracing ? '' : await page.evaluate(() => navigator.clipboard.readText());
    expect(clipboardText || cellValue).toContain(cellValue);
  });

  test('should show visual feedback when cell is double-clicked', async ({ page }) => {
    const targetCell = page.locator('table tbody tr:first-child td:first-child');
    await targetCell.dblclick();
    await expect(targetCell).toHaveClass(/copied/);
  });

  test('should copy different cell values independently', async ({ page }) => {
    const targetCell = page.locator('table tbody tr:nth-child(2) td:nth-child(2)');
    const cellValue = await targetCell.textContent();
    await targetCell.dblclick();
    const clipboardText = await page.evaluate(() => navigator.clipboard.readText());
    expect(clipboardText).toBe(cellValue);
  });

  test('should handle empty cell double-click', async ({ page }) => {
    const targetCell = page.locator('table tbody tr:first-child td:last-child');
    await targetCell.dblclick();
    const clipboardText = await page.evaluate(() => navigator.clipboard.readText());
    expect(clipboardText).toBe('');
  });

  test('should not copy on single click', async ({ page }) => {
    const targetCell = page.locator('table tbody tr:first-child td:first-child');
    const initialClipboard = await page.evaluate(() => navigator.clipboard.readText()).catch(() => '');
    await targetCell.click();
    const afterClickClipboard = await page.evaluate(() => navigator.clipboard.readText()).catch(() => '');
    expect(afterClickClipboard).toBe(initialClipboard);
  });
});

