  });

  test('should render virtual scroll list without lag', async ({ page }) => {
    const virtualList = page.locator('[data-testid="virtual-list"]');
    await expect(virtualList).toBeVisible();
    const listItems = page.locator('[data-testid="list-item"]');
    await expect(listItems).toHaveCount(0, { timeout: 1000 }).catch(() => true);
    const itemCount = await listItems.count();
    expect(itemCount).toBeGreaterThan(0);
  });

  test('should display correct number of total rows', async ({ page }) => {
    const totalRows = page.locator('[data-testid="total-rows"]');
    await expect(totalRows).toContainText('10000');
  });

  test('should scroll through list smoothly', async ({ page }) => {
    const virtualList = page.locator('[data-testid="virtual-list"]');
    await virtualList.scrollIntoViewIfNeeded();
    await virtualList.evaluate(el => el.scrollTop = el.scrollHeight);
    await page.waitForTimeout(1000);
    const firstItem = page.locator('[data-testid="list-item"]').first();
    await expect(firstItem).toBeVisible();
  });

  test('should load items dynamically as user scrolls', async ({ page }) => {
    const virtualList = page.locator('[data-testid="virtual-list"]');
    await virtualList.evaluate(el => el.scrollTop = 500);
    let itemCount = await page.locator('[data-testid="list-item"]').count();
    expect(itemCount).toBeGreaterThan(5);
    await virtualList.evaluate(el => el.scrollTop = 2000);
    await page.waitForTimeout(500);
    const items = page.locator('[data-testid="list-item"]');
    await expect(items.first()).toExist();
  });

  test('should maintain performance during rapid scrolling', async ({ page }) => {
    const virtualList = page.locator('[data-testid="virtual-list"]');
    const startTime = Date.now();
    await virtualList.evaluate(el => el.scrollTop = el.scrollHeight);
    await page.waitForTimeout(500);
    await virtualList.evaluate(el => el.scrollTop = 0);
    const endTime = Date.now();
    expect(endTime - startTime).toBeLessThan(3000);
  });

  test('should display correct row content at specific scroll positions', async ({ page }) => {
    const virtualList = page.locator('[data-testid="virtual-list"]');
    await virtualList.evaluate(el => el.scrollTop = 1000);
    await page.waitForTimeout(300);
    const firstItem = page.locator('[data-testid="list-item"]').first();
