    }, { action: 'drag-drop' });

    cy.get('[data-testid="file-list"]').should('contain', fileName);
    cy.get('[data-testid="upload-status"]').should('contain', 'Upload successful');
  });

  it('should display error message when dragging invalid file type', () => {
    const fileName = 'invalid-file.exe';
    const fileContent = 'Invalid content';

    cy.get('[data-testid="drop-zone"]').selectFile({
      contents: Cypress.Buffer.from(fileContent),
      fileName: fileName,
      mimeType: 'application/octet-stream'
    }, { action: 'drag-drop' });

    cy.get('[data-testid="error-message"]').should('be.visible').and('contain', 'Invalid file type');
  });

  it('should upload multiple files via drag and drop', () => {
    cy.get('[data-testid="drop-zone"]').selectFile([
      { contents: Cypress.Buffer.from('File 1'), fileName: 'file1.txt', mimeType: 'text/plain' },
      { contents: Cypress.Buffer.from('File 2'), fileName: 'file2.txt', mimeType: 'text/plain' }
    ], { action: 'drag-drop' });

    cy.get('[data-testid="file-list"] li').should('have.length', 2);
