describe('File Upload - Maximum Size Limit', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display error when file exceeds maximum size limit', () => {
    const maxSizeInMB = 5;
    const oversizedFileSizeInBytes = (maxSizeInMB + 1) * 1024 * 1024;

    cy.get('input[type="file"]').then(($input) => {
      const blob = new Blob(['a'.repeat(oversizedFileSizeInBytes)], { type: 'application/octet-stream' });
      const file = new File([blob], 'oversized-file.txt', { type: 'application/octet-stream' });
      const dataTransfer = new DataTransfer();
      dataTransfer.items.add(file);
      $input[0].files = dataTransfer.files;
      cy.wrap($input).trigger('change', { force: true });
    });

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'File size exceeds maximum limit');
  });

  it('should not display error when file is within size limit', () => {
    cy.get('input[type="file"]').then(($input) => {
      const blob = new Blob(['valid content'], { type: 'text/plain' });
      const file = new File([blob], 'valid-file.txt', { type: 'text/plain' });
      const dataTransfer = new DataTransfer();
      dataTransfer.items.add(file);
      $input[0].files = dataTransfer.files;
      cy.wrap($input).trigger('change', { force: true });
    });

    cy.get('[data-testid="error-message"]').should('not.exist');
  });

  it('should display specific error message with file size information', () => {
    const maxSizeInMB = 5;
    const oversizedFileSizeInBytes = (maxSizeInMB + 2) * 1024 * 1024;

    cy.get('input[type="file"]').then(($input) => {
      const blob = new Blob(['a'.repeat(oversizedFileSizeInBytes)], { type: 'application/octet-stream' });
      const file = new File([blob], 'large-file.bin', { type: 'application/octet-stream' });
      const dataTransfer = new DataTransfer();
      dataTransfer.items.add(file);
      $input[0].files = dataTransfer.files;
      cy.wrap($input).trigger('change', { force: true });
    });

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', '5 MB');
  });
});

