    await downloadPromise;
    await expect(progressIndicator).not.toBeVisible();
  });

  test('should display success message after download', async ({ page, context }) => {
    const downloadPromise = context.waitForEvent('download');
    await page.locator('[data-testid="file-item"]').first().locator('[data-testid="download-btn"]').click();
    await downloadPromise;
    const successToast = page.locator('[data-testid="success-toast"]');
