    const errorToast = page.locator('[data-testid="error-toast"]');
    await expect(errorToast).toContainText('Failed to download file');
  });

  test('should allow downloading multiple files sequentially', async ({ page, context }) => {
    let downloadPromise = context.waitForEvent('download');
