    await page.goto('/');
  });

  test('should highlight upload area when dragging file over it', async ({ page }) => {
    const uploadArea = page.locator('[data-testid="upload-area"]');

    await expect(uploadArea).toBeVisible();
    await expect(uploadArea).not.toHaveClass(/highlight/);

    await uploadArea.dispatchEvent('dragenter', {
      dataTransfer: {
        types: ['Files']
      }
    });

    await expect(uploadArea).toHaveClass(/highlight/);
  });

  test('should remove highlight when dragging file out of upload area', async ({ page }) => {
    const uploadArea = page.locator('[data-testid="upload-area"]');

    await uploadArea.dispatchEvent('dragenter', {
      dataTransfer: {
        types: ['Files']
      }
    });

    await expect(uploadArea).toHaveClass(/highlight/);

    await uploadArea.dispatchEvent('dragleave');

    await expect(uploadArea).not.toHaveClass(/highlight/);
  });

  test('should maintain highlight during dragover', async ({ page }) => {
    const uploadArea = page.locator('[data-testid="upload-area"]');

    await uploadArea.dispatchEvent('dragenter', {
      dataTransfer: {
        types: ['Files']
      }
    });

    await uploadArea.dispatchEvent('dragover');

    await expect(uploadArea).toHaveClass(/highlight/);
  });

  test('should remove highlight after file drop', async ({ page }) => {
    const uploadArea = page.locator('[data-testid="upload-area"]');

    await uploadArea.dispatchEvent('dragenter', {
      dataTransfer: {
        types: ['Files']
      }
    });

    const dataTransfer = await page.evaluateHandle(() => {
      const dt = new DataTransfer();
      const file = new File(['content'], 'test.txt', { type: 'text/plain' });
      dt.items.add(file);
      return dt;
    });

    await uploadArea.dispatchEvent('drop', { dataTransfer });

    await expect(uploadArea).not.toHaveClass(/highlight/);
  });
});

