  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/upload');
  });

  test('should display success checkmark when file is fully uploaded', async ({ page }) => {
    const fileInput = await page.locator('input[type="file"]');
    await fileInput.setInputFiles('tests/fixtures/sample.pdf');

    const progressBar = await page.locator('.upload-progress');
    await expect(progressBar).toBeVisible();
    await expect(progressBar).not.toBeVisible({ timeout: 10000 });

    const checkmark = await page.locator('.success-checkmark');
    await expect(checkmark).toBeVisible();
    await expect(checkmark).toHaveClass(/checkmark-icon/);
  });

  test('should show success message with checkmark', async ({ page }) => {
    const fileInput = await page.locator('input[type="file"]');
    await fileInput.setInputFiles('tests/fixtures/document.txt');

    const uploadStatus = await page.locator('.upload-status');
    await expect(uploadStatus).toContainText('Uploading');

    const checkmark = await page.locator('.success-checkmark');
    await expect(checkmark).toBeVisible({ timeout: 15000 });
    await expect(uploadStatus).toContainText('Upload complete');
  });

  test('should display checkmark after multiple file uploads', async ({ page }) => {
    const fileInput = await page.locator('input[type="file"]');
    await fileInput.setInputFiles('tests/fixtures/file1.pdf');

    let checkmark = await page.locator('.success-checkmark');
    await expect(checkmark).toBeVisible({ timeout: 15000 });

    const uploadAgainBtn = await page.locator('.upload-again-btn');
    await uploadAgainBtn.click();

    await fileInput.setInputFiles('tests/fixtures/file2.pdf');
    checkmark = await page.locator('.success-checkmark');
    await expect(checkmark).toBeVisible({ timeout: 15000 });
  });

  test('should animate checkmark appearance', async ({ page }) => {
    const fileInput = await page.locator('input[type="file"]');
    await fileInput.setInputFiles('tests/fixtures/sample.pdf');

    const checkmark = await page.locator('.success-checkmark');
    await expect(checkmark).toBeVisible({ timeout: 15000 });
    await expect(checkmark).toHaveClass(/animate-checkmark/);
  });
});

