describe('Image Paste from Clipboard', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should paste image from clipboard into upload area', () => {
    const fileName = 'test-image.png';
    const fileType = 'image/png';
    const fixturePath = 'images/sample.png';

    cy.get('[data-testid="upload-area"]').should('be.visible');

    cy.fixture(fixturePath, 'base64').then((fileContent) => {
      cy.get('[data-testid="upload-area"]').trigger('paste', {
        clipboardData: {
          items: [
            {
              kind: 'file',
              type: fileType,
              getAsFile: () => new File([Cypress.Blob.base64StringToBlob(fileContent)], fileName, { type: fileType })
            }
          ],
          getData: (type) => fileContent
        }
      });
    });

    cy.get('[data-testid="upload-preview"]').should('be.visible');
    cy.get('[data-testid="file-name"]').should('contain', fileName);
    cy.get('[data-testid="upload-status"]').should('contain', 'File ready to upload');
  });

  it('should handle paste event on upload input', () => {
    const imageData = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==';

    cy.get('[data-testid="upload-input"]').trigger('paste', {
      clipboardData: {
        getData: () => imageData,
        items: [{ type: 'image/png' }]
      }
    });

    cy.get('[data-testid="upload-preview"]').should('exist');
  });

  it('should reject non-image files from clipboard', () => {
    cy.get('[data-testid="upload-area"]').trigger('paste', {
      clipboardData: {
        items: [{ type: 'text/plain' }],
        getData: () => 'plain text'
      }
    });

    cy.get('[data-testid="error-message"]').should('contain', 'Please paste an image file');
    cy.get('[data-testid="upload-preview"]').should('not.exist');
  });

  it('should display uploaded image preview after paste', () => {
    cy.fixture('images/sample.png', 'base64').then((fileContent) => {
      cy.get('[data-testid="upload-area"]').trigger('paste', {
        clipboardData: {
          items: [{ type: 'image/png', getAsFile: () => new File([Cypress.Blob.base64StringToBlob(fileContent)], 'image.png', { type: 'image/png' }) }]
        }
      });
    });

    cy.get('[data-testid="image-preview"]').should('be.visible');
    cy.get('[data-testid="image-preview"]').should('have.attr', 'src');
  });
});

