import { test, expect, Page } from '@playwright/test';

test.describe('Image Paste from Clipboard', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('/');
  });

  test('should paste image from clipboard into upload area', async () => {
    const uploadArea = page.locator('[data-testid="upload-area"]');
    await expect(uploadArea).toBeVisible();

    const imageBuffer = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==', 'base64');

    await page.evaluate((buffer) => {
      const dataTransfer = new DataTransfer();
      const file = new File([new Uint8Array(buffer)], 'test-image.png', { type: 'image/png' });
      dataTransfer.items.add(file);
      const pasteEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer });
      document.querySelector('[data-testid="upload-area"]').dispatchEvent(pasteEvent);
    }, Array.from(imageBuffer));

    await expect(page.locator('[data-testid="upload-preview"]')).toBeVisible();
    await expect(page.locator('[data-testid="file-name"]')).toContainText('test-image.png');
  });

  test('should handle paste event on upload input', async () => {
    const uploadInput = page.locator('[data-testid="upload-input"]');

    await page.evaluate(() => {
      const dataTransfer = new DataTransfer();
      const blob = new Blob(['image data'], { type: 'image/png' });
      const file = new File([blob], 'image.png', { type: 'image/png' });
      dataTransfer.items.add(file);
      const pasteEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer });
      document.querySelector('[data-testid="upload-input"]').dispatchEvent(pasteEvent);
    });

    await expect(page.locator('[data-testid="upload-preview"]')).toBeVisible();
  });

  test('should reject non-image files from clipboard', async () => {
    await page.evaluate(() => {
      const dataTransfer = new DataTransfer();
      const file = new File(['text content'], 'document.txt', { type: 'text/plain' });
      dataTransfer.items.add(file);
      const pasteEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer });
      document.querySelector('[data-testid="upload-area"]').dispatchEvent(pasteEvent);
    });

    await expect(page.locator('[data-testid="error-message"]')).toContainText('Please paste an image file');
    await expect(page.locator('[data-testid="upload-preview"]')).not.toBeVisible();
  });

  test('should display uploaded image preview after paste', async () => {
    await page.evaluate(() => {
      const dataTransfer = new DataTransfer();
      const blob = new Blob(['PNG image data'], { type: 'image/png' });
      const file = new File([blob], 'sample.png', { type: 'image/png' });
      dataTransfer.items.add(file);
      const pasteEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer });
      document.querySelector('[data-testid="upload-area"]').dispatchEvent(pasteEvent);
    });

    const imagePreview = page.locator('[data-testid="image-preview"]');
    await expect(imagePreview).toBeVisible();
    await expect(imagePreview).toHaveAttribute('src', /.+/);
  });
});

