describe('File Upload Virus Scan Status', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should display virus scan status for uploaded file', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/test-file.txt');
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="scan-status"]').should('be.visible');
    cy.get('[data-testid="scan-status"]').should('contain', 'Scanning');
  });

  it('should show scan complete status', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/test-file.txt');
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="scan-status"]', { timeout: 10000 }).should('contain', 'Scan Complete');
  });

  it('should display clean status for safe files', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/safe-file.pdf');
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="scan-result"]', { timeout: 10000 }).should('contain', 'Clean');
    cy.get('[data-testid="scan-icon"]').should('have.class', 'icon-safe');
  });

  it('should display threat detected status for infected files', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/infected-file.exe');
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="scan-result"]', { timeout: 10000 }).should('contain', 'Threat Detected');
    cy.get('[data-testid="scan-icon"]').should('have.class', 'icon-threat');
  });

  it('should show scan progress bar during scanning', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/large-file.zip');
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="progress-bar"]').should('be.visible');
    cy.get('[data-testid="progress-bar"]').should('have.attr', 'aria-valuenow');
  });

  it('should display scan status for multiple files', () => {
    cy.get('input[type="file"]').selectFile([
      'cypress/fixtures/file1.txt',
      'cypress/fixtures/file2.txt'
    ]);
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="file-scan-item"]').should('have.length', 2);
    cy.get('[data-testid="file-scan-item"]').each(($item) => {
      cy.wrap($item).find('[data-testid="scan-status"]').should('be.visible');
    });
