describe('File Upload - Title and Description', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should upload a file and set title and description', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/test-file.pdf');
    cy.get('input[name="title"]').type('Test Document');
    cy.get('textarea[name="description"]').type('This is a test document for verification');
    cy.get('button[type="submit"]').click();
    cy.get('.success-message').should('be.visible');
  });

  it('should display uploaded file with title and description', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/test-file.pdf');
    cy.get('input[name="title"]').type('My File');
    cy.get('textarea[name="description"]').type('File description here');
    cy.get('button[type="submit"]').click();
    cy.get('.file-item').should('contain', 'My File');
    cy.get('.file-description').should('contain', 'File description here');
  });

  it('should validate title is required', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/test-file.pdf');
    cy.get('textarea[name="description"]').type('Description only');
    cy.get('button[type="submit"]').click();
    cy.get('.error-message').should('contain', 'Title is required');
  });

  it('should allow editing title and description after upload', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/test-file.pdf');
    cy.get('input[name="title"]').type('Original Title');
    cy.get('textarea[name="description"]').type('Original description');
    cy.get('button[type="submit"]').click();
    cy.get('.file-item .edit-btn').click();
    cy.get('input[name="title"]').clear().type('Updated Title');
    cy.get('textarea[name="description"]').clear().type('Updated description');
    cy.get('button[type="submit"]').click();
    cy.get('.file-item').should('contain', 'Updated Title');
    cy.get('.file-description').should('contain', 'Updated description');
  });

  it('should handle multiple file uploads with different titles and descriptions', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/file1.pdf');
    cy.get('input[name="title"]').type('File One');
    cy.get('textarea[name="description"]').type('First file');
    cy.get('button[type="submit"]').click();
    cy.get('input[type="file"]').selectFile('cypress/fixtures/file2.pdf');
    cy.get('input[name="title"]').type('File Two');
    cy.get('textarea[name="description"]').type('Second file');
    cy.get('button[type="submit"]').click();
    cy.get('.file-item').should('have.length', 2);
    cy.get('.file-item').first().should('contain', 'File One');
    cy.get('.file-item').last().should('contain', 'File Two');
  });
});

