describe('File Upload Organization into Folders', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/upload');
  });

  it('Should create a new folder for file organization', () => {
    cy.get('[data-testid="create-folder-btn"]').click();
    cy.get('[data-testid="folder-name-input"]').type('My Documents');
    cy.get('[data-testid="confirm-folder-btn"]').click();
    cy.get('[data-testid="folder-list"]').should('contain', 'My Documents');
  });

  it('Should upload file and assign to folder', () => {
    cy.get('[data-testid="folder-list"]').contains('My Documents').click();
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf');
    cy.get('[data-testid="upload-btn"]').click();
    cy.get('[data-testid="file-list"]').should('contain', 'sample.pdf');
  });

  it('Should organize multiple files in same folder', () => {
    cy.get('[data-testid="folder-list"]').contains('My Documents').click();
    cy.get('[data-testid="file-input"]').selectFile(['cypress/fixtures/file1.pdf', 'cypress/fixtures/file2.docx']);
    cy.get('[data-testid="upload-btn"]').click();
    cy.get('[data-testid="file-list"]').should('contain', 'file1.pdf');
    cy.get('[data-testid="file-list"]').should('contain', 'file2.docx');
  });

  it('Should move file between folders', () => {
    cy.get('[data-testid="folder-list"]').contains('My Documents').click();
    cy.get('[data-testid="file-item"]').first().rightclick();
    cy.get('[data-testid="move-file-option"]').click();
    cy.get('[data-testid="folder-select"]').select('Archives');
    cy.get('[data-testid="confirm-move-btn"]').click();
    cy.get('[data-testid="file-list"]').should('not.contain', 'sample.pdf');
  });

  it('Should display folder structure in breadcrumb', () => {
    cy.get('[data-testid="folder-list"]').contains('My Documents').click();
    cy.get('[data-testid="breadcrumb"]').should('contain', 'Home');
    cy.get('[data-testid="breadcrumb"]').should('contain', 'My Documents');
  });

  it('Should delete empty folder', () => {
    cy.get('[data-testid="folder-item"]').contains('Empty Folder').rightclick();
    cy.get('[data-testid="delete-folder-option"]').click();
    cy.get('[data-testid="confirm-delete-btn"]').click();
    cy.get('[data-testid="folder-list"]').should('not.contain', 'Empty Folder');
  });
});

