import { test, expect } from '@playwright/test';

test.describe('Faceted Search - No Page Reload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/search');
    await page.fill('[data-testid="search-input"]', 'laptop');
    await page.click('[data-testid="search-button"]');
    await page.waitForSelector('[data-testid="search-results"]');
  });

  test('should update results when clicking price filter without page reload', async ({ page }) => {
    const navigationPromise = page.waitForNavigation().catch(() => null);
    await page.click('[data-testid="filter-price-range"]');
    await page.click('[data-testid="price-option-500"]');
    await page.waitForSelector('[data-testid="search-results"]');
    const navigationOccurred = await Promise.race([
      navigationPromise,
      new Promise(resolve => setTimeout(() => resolve(false), 1000))
    ]);
    expect(navigationOccurred).toBeFalsy();
  });

  test('should update results when clicking category filter without page reload', async ({ page }) => {
    const url1 = page.url();
    await page.click('[data-testid="filter-category"]');
    await page.click('[data-testid="category-option-electronics"]');
    await page.waitForSelector('[data-testid="search-results"]');
    const url2 = page.url();
    expect(url2).not.toBe(url1);
    const resultsText = await page.textContent('[data-testid="search-results"]');
    expect(resultsText).toContain('electronics');
  });

  test('should apply multiple facet filters simultaneously', async ({ page }) => {
    await page.click('[data-testid="filter-brand"]');
    await page.click('[data-testid="brand-option-dell"]');
    await page.click('[data-testid="filter-price-range"]');
    await page.click('[data-testid="price-option-1000"]');
    await page.waitForSelector('[data-testid="search-results"]');
    const appliedFilters = await page.textContent('[data-testid="applied-filters"]');
    expect(appliedFilters).toContain('dell');
    expect(appliedFilters).toContain('1000');
  });

  test('should update result count dynamically when filter applied', async ({ page }) => {
    const initialCount = await page.textContent('[data-testid="result-count"]');
    const count = parseInt(initialCount || '0');
    await page.click('[data-testid="filter-availability"]');
    await page.click('[data-testid="availability-in-stock"]');
    await page.waitForTimeout(500);
    const newCount = await page.textContent('[data-testid="result-count"]');
    expect(parseInt(newCount || '0')).toBeLessThanOrEqual(count);
  });

  test('should clear filter and restore original results', async ({ page }) => {
    await page.click('[data-testid="filter-price-range"]');
    await page.click('[data-testid="price-option-500"]');
    await page.click('[data-testid="clear-filter-btn"]');
    await page.waitForSelector('[data-testid="search-results"]');
    const appliedFilters = await page.textContent('[data-testid="applied-filters"]');
    expect(appliedFilters?.trim()).toBe('');
  });
});

