describe('Image Alt Text Accessibility', () => {
  beforeEach(() => {
    cy.visit('/')
  })

  it('should have alt text on all images', () => {
    cy.get('img').each(($img) => {
      cy.wrap($img).should('have.attr', 'alt')
      cy.wrap($img).invoke('attr', 'alt').should('not.be.empty')
    })
  })

  it('should have descriptive alt text not just filename', () => {
    cy.get('img').each(($img) => {
      const alt = $img.attr('alt')
      expect(alt).to.exist
      expect(alt.length).to.be.greaterThan(3)
      expect(alt).not.to.match(/\.(jpg|png|gif|webp)$/i)
    })
  })

  it('should announce images with alt text to screen readers', () => {
    cy.get('img[alt]').first().should('have.attr', 'alt')
    cy.get('img[alt]').first().invoke('attr', 'alt').then((altText) => {
      expect(altText).to.match(/^[a-zA-Z].+[a-zA-Z0-9]$/)
    })
  })

  it('should not have decorative images with empty alt', () => {
    cy.get('img:not([role="presentation"]):not([aria-hidden="true"])').each(($img) => {
      const alt = $img.attr('alt')
      expect(alt).to.exist
      if (alt === '') {
        cy.wrap($img).should('have.attr', 'aria-hidden', 'true').or('have.attr', 'role', 'presentation')
      }
    })
  })

  it('should have meaningful alt text for images in buttons', () => {
    cy.get('button img').each(($img) => {
      cy.wrap($img).should('have.attr', 'alt')
      cy.wrap($img).invoke('attr', 'alt').should('have.length.greaterThan', 0)
    })
  })
})

