describe('Keyboard Navigation - Tab Focus', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should navigate all interactive elements using Tab key', () => {
    // Get all focusable elements
    cy.get('button, a, input, textarea, select, [tabindex]:not([tabindex="-1"])').then(($elements) => {
      expect($elements.length).to.be.greaterThan(0);
    });

    // Start from document root
    cy.focused().should('not.exist');

    // Tab through first element
    cy.get('body').tab();
    cy.focused().should('have.attr', 'role').and('not.equal', 'presentation');
  });

  it('should maintain logical tab order', () => {
    cy.get('body').tab();
    cy.focused().as('firstElement');

    cy.get('body').tab();
    cy.focused().as('secondElement');

    cy.get('@firstElement').then(($first) => {
      cy.get('@secondElement').then(($second) => {
        expect($first[0]).not.to.equal($second[0]);
      });
    });
  });

  it('should focus all interactive buttons', () => {
    const buttons = [];
    cy.get('button:visible').each(($btn) => {
      buttons.push($btn);
    }).then(() => {
      buttons.forEach(() => {
        cy.get('body').tab();
        cy.focused().should('be.visible');
      });
    });
  });

  it('should focus all interactive links', () => {
    cy.get('a:visible').each(() => {
      cy.get('body').tab();
      cy.focused().should('have.attr', 'href');
    });
  });

  it('should focus all form inputs', () => {
    cy.get('input:visible, textarea:visible, select:visible').each(() => {
      cy.get('body').tab();
      cy.focused().should('be.visible');
    });
  });

  it('should skip elements with tabindex -1', () => {
    cy.get('[tabindex="-1"]').should('have.length.greaterThan', 0);
    cy.get('body').tab();
    cy.focused().should('not.have.attr', 'tabindex', '-1');
  });

  it('should have visible focus indicator on tabbed elements', () => {
    cy.get('body').tab();
    cy.focused().should('have.css', 'outline').or('have.css', 'box-shadow').or('have.css', 'border');
  });
});

