import { test, expect, Page } from '@playwright/test';

test.describe('Keyboard Navigation - Tab Focus', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('/');
  });

  test.afterEach(async () => {
    await page.close();
  });

  test('should navigate all interactive elements using Tab key', async () => {
    const focusableElements = page.locator('button, a, input, textarea, select, [tabindex]:not([tabindex="-1"])');
    const count = await focusableElements.count();
    expect(count).toBeGreaterThan(0);

    await page.keyboard.press('Tab');
    const focusedElement = await page.evaluate(() => document.activeElement?.tagName);
    expect(focusedElement).toBeTruthy();
  });

  test('should maintain logical tab order', async () => {
    await page.keyboard.press('Tab');
    const firstFocused = await page.evaluate(() => (document.activeElement as HTMLElement)?.id);

    await page.keyboard.press('Tab');
    const secondFocused = await page.evaluate(() => (document.activeElement as HTMLElement)?.id);

    expect(firstFocused).not.toBe(secondFocused);
  });

  test('should focus all visible buttons', async () => {
    const buttons = page.locator('button:visible');
    const buttonCount = await buttons.count();

    for (let i = 0; i < buttonCount; i++) {
      await page.keyboard.press('Tab');
      const isFocusedButton = await page.evaluate(
        () => (document.activeElement as HTMLElement)?.tagName === 'BUTTON'
      );
      expect(isFocusedButton).toBeTruthy();
    }
  });

  test('should focus all visible links', async () => {
    const links = page.locator('a:visible');
    const linkCount = await links.count();

    for (let i = 0; i < linkCount; i++) {
      await page.keyboard.press('Tab');
      const isFocusedLink = await page.evaluate(
        () => (document.activeElement as HTMLElement)?.tagName === 'A'
      );
      if (isFocusedLink) {
        expect(isFocusedLink).toBeTruthy();
      }
    }
  });

  test('should focus all form inputs', async () => {
    const inputs = page.locator('input:visible, textarea:visible, select:visible');
    const inputCount = await inputs.count();

    for (let i = 0; i < inputCount; i++) {
      await page.keyboard.press('Tab');
      const isVisible = await page.evaluate(
        () => window.getComputedStyle(document.activeElement as HTMLElement).display !== 'none'
      );
      expect(isVisible).toBeTruthy();
    }
  });

  test('should skip elements with tabindex -1', async () => {
    const skippedElements = page.locator('[tabindex="-1"]');
    const skippedCount = await skippedElements.count();
    expect(skippedCount).toBeGreaterThan(0);

    await page.keyboard.press('Tab');
    const tabindex = await page.evaluate(
      () => (document.activeElement as HTMLElement)?.getAttribute('tabindex')
    );
    expect(tabindex).not.toBe('-1');
  });

  test('should have visible focus indicator on tabbed elements', async () => {
    await page.keyboard.press('Tab');
    const hasFocusIndicator = await page.evaluate(() => {
      const element = document.activeElement as HTMLElement;
      const styles = window.getComputedStyle(element);
      return (
        styles.outline !== 'none' ||
        styles.boxShadow !== 'none' ||
        styles.border !== 'none'
      );
    });
    expect(hasFocusIndicator).toBeTruthy();
  });
});

