describe('Screen Reader Error Message Announcements', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should announce error messages to screen readers when form validation fails', () => {
    cy.get('input[name="email"]').clear();
    cy.get('button[type="submit"]').click();
    cy.get('[role="alert"]').should('exist').and('be.visible');
    cy.get('[role="alert"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[role="alert"]').contains('Email is required');
  });

  it('should use aria-live="assertive" for critical error messages', () => {
    cy.get('input[name="password"]').clear();
    cy.get('button[type="submit"]').click();
    cy.get('[role="alert"][aria-live="assertive"]').should('exist');
  });

  it('should associate error messages with form fields using aria-describedby', () => {
    cy.get('input[name="username"]').clear();
    cy.get('button[type="submit"]').click();
    cy.get('input[name="username"]').should('have.attr', 'aria-describedby');
    const describedById = cy.get('input[name="username"]').invoke('attr', 'aria-describedby');
    cy.get(`#${describedById}`).should('contain', 'Username is required');
  });

  it('should announce multiple error messages in sequence', () => {
    cy.get('input[name="email"]').clear();
    cy.get('input[name="password"]').clear();
    cy.get('button[type="submit"]').click();
    cy.get('[role="alert"]').should('have.length', 2);
    cy.get('[role="alert"]').first().should('contain', 'Email is required');
    cy.get('[role="alert"]').last().should('contain', 'Password is required');
  });

  it('should update live region when error is dynamically added', () => {
    cy.get('input[name="email"]').type('invalid-email');
    cy.get('button[type="submit"]').click();
    cy.get('[aria-live="polite"]').should('be.visible');
    cy.get('[aria-live="polite"]').should('contain', 'Invalid email format');
  });

  it('should remove error announcements when user corrects input', () => {
    cy.get('input[name="email"]').clear();
    cy.get('button[type="submit"]').click();
    cy.get('[role="alert"]').should('exist');
    cy.get('input[name="email"]').type('test@example.com');
    cy.get('[role="alert"][aria-hidden="true"]').should('exist');
  });

  it('should have accessible error message containers', () => {
    cy.get('input[name="phone"]').clear();
    cy.get('button[type="submit"]').click();
    cy.get('.error-container').should('have.attr', 'role', 'alert');
    cy.get('.error-container').should('have.attr', 'aria-live');
  });
});

