describe('Dropdown Escape Key Accessibility', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should close dropdown when Escape key is pressed', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');
    cy.get('[data-testid="dropdown-menu"]').parent().type('{esc}');
    cy.get('[data-testid="dropdown-menu"]').should('not.be.visible');
  });

  it('should close dropdown menu with keyboard focus on trigger button', () => {
    cy.get('[data-testid="dropdown-trigger"]').focus().click();
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');
    cy.focused().type('{esc}');
    cy.get('[data-testid="dropdown-menu"]').should('not.be.visible');
  });

  it('should close dropdown when pressing Escape from menu item', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');
    cy.get('[data-testid="dropdown-item"]').first().focus();
    cy.focused().type('{esc}');
    cy.get('[data-testid="dropdown-menu"]').should('not.be.visible');
  });

  it('should restore focus to trigger button after closing dropdown with Escape', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');
    cy.get('[data-testid="dropdown-item"]').first().focus();
    cy.focused().type('{esc}');
    cy.get('[data-testid="dropdown-trigger"]').should('have.focus');
  });

  it('should not close dropdown when Escape is pressed on unrelated element', () => {
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');
    cy.get('[data-testid="other-input"]').focus().type('{esc}');
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');
  });
});

