describe('Reading Order Accessibility Tests', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should verify reading order matches visual order using tab navigation', () => {
    cy.get('body').then(() => {
      let previousTabIndex = -1;
      cy.get('[tabindex], button, a, input, select, textarea').each(($el) => {
        const tabindex = $el.attr('tabindex') || '0';
        cy.wrap($el).should('be.visible');
      });
    });
  });

  it('should verify DOM order matches visual order', () => {
    cy.get('main').within(() => {
      cy.get('h1, h2, h3, p, button, a').then(($elements) => {
        const positions = Array.from($elements).map((el) => ({
          text: el.textContent.trim(),
          top: el.getBoundingClientRect().top,
        }));
        for (let i = 1; i < positions.length; i++) {
          expect(positions[i].top).to.be.greaterThanOrEqual(positions[i - 1].top);
        }
      });
    });
  });

  it('should not have content hidden from screen readers out of order', () => {
    cy.get('[aria-hidden="true"]').each(($el) => {
      cy.wrap($el).should('not.have.css', 'display', 'block');
    });
  });

  it('should have proper heading hierarchy in reading order', () => {
    cy.get('h1, h2, h3, h4, h5, h6').then(($headings) => {
      let previousLevel = 0;
      $headings.each((index, heading) => {
        const level = parseInt(heading.tagName[1]);
        expect(level - previousLevel).to.be.lessThanOrEqual(1);
        previousLevel = level;
      });
    });
  });

  it('should verify logical tab order for interactive elements', () => {
    const focusedElements = [];
    cy.get('body').then(() => {
      cy.focused().then(($el) => {
        focusedElements.push($el);
      });
      for (let i = 0; i < 10; i++) {
        cy.focused().trigger('keydown', { keyCode: 9, which: 9 });
        cy.focused().then(($el) => {
          cy.wrap($el).should('exist');
          focusedElements.push($el);
        });
      }
    });
  });

  it('should ensure skip links appear first in reading order', () => {
    cy.get('a[href="#main"], a.skip-link').first().then(($skipLink) => {
      cy.get('body').children().first().then(($firstElement) => {
        expect($skipLink.length).to.be.greaterThan(0);
      });
    });
  });
});

