    const focusableElements = await page.locator('button, a, input, select, textarea, [tabindex]').all();
    expect(focusableElements.length).toBeGreaterThan(0);
    for (const element of focusableElements) {
      const isVisible = await element.isVisible();
      expect(isVisible).toBeTruthy();
    }
  });

  test('should verify DOM order matches visual order', async ({ page }) => {
    const elements = await page.locator('main h1, main h2, main h3, main p, main button, main a').all();
    const positions = [];
    for (const element of elements) {
      const box = await element.boundingBox();
      positions.push({
        text: await element.textContent(),
        top: box?.y || 0,
      });
    }
    for (let i = 1; i < positions.length; i++) {
      expect(positions[i].top).toBeGreaterThanOrEqual(positions[i - 1].top);
    }
  });

  test('should not have content hidden from screen readers out of order', async ({ page }) => {
    const hiddenElements = await page.locator('[aria-hidden="true"]').all();
    for (const element of hiddenElements) {
      const display = await element.evaluate((el) => window.getComputedStyle(el).display);
      expect(display).not.toBe('block');
    }
  });

  test('should have proper heading hierarchy in reading order', async ({ page }) => {
    const headings = await page.locator('h1, h2, h3, h4, h5, h6').all();
    let previousLevel = 0;
    for (const heading of headings) {
      const tagName = await heading.evaluate((el) => el.tagName);
      const level = parseInt(tagName[1]);
      expect(level - previousLevel).toBeLessThanOrEqual(1);
      previousLevel = level;
    }
  });

  test('should verify logical tab order for interactive elements', async ({ page }) => {
    await page.keyboard.press('Tab');
    let previousElement = await page.locator(':focus');
    expect(previousElement).toBeDefined();
    for (let i = 0; i < 10; i++) {
      await page.keyboard.press('Tab');
      const currentElement = await page.locator(':focus');
      expect(currentElement).toBeDefined();
    }
  });

  test('should ensure skip links appear first in reading order', async ({ page }) => {
    const skipLink = await page.locator('a[href="#main"], a.skip-link').first();
    const isVisible = await skipLink.isVisible().catch(() => false);
    const skipLinkExists = await skipLink.count().then((count) => count > 0).catch(() => false);
    expect(skipLinkExists || isVisible).toBeTruthy();
  });

  test('should verify content is accessible in logical reading order', async ({ page }) => {
    const mainContent = await page.locator('main, [role="main"]');
    const exists = await mainContent.count();
    expect(exists).toBeGreaterThan(0);
  });
});

