describe('Click Target Accessibility - 44x44px Minimum', () => {
  beforeEach(() => {
    cy.visit('/')
  })

  it('should have click targets with minimum 44x44px dimensions', () => {
    cy.get('button, a, [role="button"], input[type="checkbox"], input[type="radio"]').each(($el) => {
      cy.wrap($el).then(($element) => {
        const width = $element.outerWidth()
        const height = $element.outerHeight()
        expect(width).to.be.at.least(44, `Button width ${width}px is less than 44px`)
        expect(height).to.be.at.least(44, `Button height ${height}px is less than 44px`)
      })
    })
  })

  it('should verify padding provides adequate touch target area', () => {
    cy.get('button').each(($btn) => {
      cy.wrap($btn).then(($element) => {
        const rect = $element[0].getBoundingClientRect()
        const targetSize = Math.min(rect.width, rect.height)
        expect(targetSize).to.be.at.least(44)
      })
    })
  })

  it('should ensure interactive elements are not too close together', () => {
    cy.get('button, a[href]').each(($el, index) => {
      if (index < cy.get('button, a[href]').length - 1) {
        cy.wrap($el).then(($element) => {
          const rect1 = $element[0].getBoundingClientRect()
          cy.get('button, a[href]').eq(index + 1).then(($next) => {
            const rect2 = $next[0].getBoundingClientRect()
            const distance = Math.min(
              Math.abs(rect1.right - rect2.left),
              Math.abs(rect2.right - rect1.left),
              Math.abs(rect1.bottom - rect2.top),
              Math.abs(rect2.bottom - rect1.top)
            )
            expect(distance).to.be.at.least(8, 'Interactive elements should have minimum 8px spacing')
          })
        })
      }
    })
  })
})

