import { test, expect } from '@playwright/test';

test.describe('Click Target Accessibility - 44x44px Minimum', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should have click targets with minimum 44x44px dimensions', async ({ page }) => {
    const interactiveElements = page.locator('button, a, [role="button"], input[type="checkbox"], input[type="radio"]');
    const count = await interactiveElements.count();

    for (let i = 0; i < count; i++) {
      const element = interactiveElements.nth(i);
      const box = await element.boundingBox();

      if (box) {
        expect(box.width).toBeGreaterThanOrEqual(44);
        expect(box.height).toBeGreaterThanOrEqual(44);
      }
    }
  });

  test('should verify all buttons meet minimum touch target size', async ({ page }) => {
    const buttons = page.locator('button');
    const count = await buttons.count();

    for (let i = 0; i < count; i++) {
      const button = buttons.nth(i);
      const box = await button.boundingBox();

      if (box) {
        const minDimension = Math.min(box.width, box.height);
        expect(minDimension).toBeGreaterThanOrEqual(44);
      }
    }
  });

  test('should ensure links have adequate click target size', async ({ page }) => {
    const links = page.locator('a[href]');
    const count = await links.count();

    for (let i = 0; i < count; i++) {
      const link = links.nth(i);
      const box = await link.boundingBox();

      if (box) {
        expect(box.width).toBeGreaterThanOrEqual(44);
        expect(box.height).toBeGreaterThanOrEqual(44);
      }
    }
  });

  test('should verify interactive elements have adequate spacing', async ({ page }) => {
    const interactive = page.locator('button, a[href], input[type="checkbox"], input[type="radio"]');
    const count = await interactive.count();

    const positions = [];
    for (let i = 0; i < count; i++) {
      const box = await interactive.nth(i).boundingBox();
      if (box) {
        positions.push(box);
      }
    }

    for (let i = 0; i < positions.length - 1; i++) {
      for (let j = i + 1; j < positions.length; j++) {
        const rect1 = positions[i];
        const rect2 = positions[j];

        const horizontalDistance = Math.min(
          Math.abs(rect1.x + rect1.width - rect2.x),
          Math.abs(rect2.x + rect2.width - rect1.x)
        );
        const verticalDistance = Math.min(
          Math.abs(rect1.y + rect1.height - rect2.y),
          Math.abs(rect2.y + rect2.height - rect1.y)
        );

        if (horizontalDistance > 0 && verticalDistance > 0) {
          const minDistance = Math.min(horizontalDistance, verticalDistance);
          expect(minDistance).toBeGreaterThanOrEqual(8);
        }
      }
    }
  });
});

