  });

  it('should display captions toggle button on video player', () => {
    cy.get('video').should('exist');
    cy.get('[data-testid="captions-toggle"]').should('be.visible');
  });

  it('should enable captions when toggle is clicked', () => {
    cy.get('[data-testid="captions-toggle"]').click();
    cy.get('[data-testid="captions-container"]').should('be.visible');
    cy.get('[data-testid="captions-toggle"]').should('have.attr', 'aria-pressed', 'true');
  });

  it('should display captions text synchronized with video', () => {
    cy.get('[data-testid="captions-toggle"]').click();
    cy.get('[data-testid="video-caption"]').should('exist');
    cy.get('[data-testid="video-caption"]').invoke('text').should('not.be.empty');
  });

  it('should disable captions when toggle is clicked again', () => {
