describe('Accessibility: Prefers Reduced Motion', () => {
  beforeEach(() => {
    cy.visit('/')
  })

  it('should respect prefers-reduced-motion: reduce setting', () => {
    cy.window().then((win) => {
      const mediaQuery = win.matchMedia('(prefers-reduced-motion: reduce)')
      expect(mediaQuery.matches).to.be.false
    })
  })

  it('should disable animations when prefers-reduced-motion is set to reduce', () => {
    cy.window().then((win) => {
      Object.defineProperty(win, 'matchMedia', {
        writable: true,
        value: (query) => ({
          matches: query === '(prefers-reduced-motion: reduce)',
          media: query,
          onchange: null,
          addListener: cy.stub(),
          removeListener: cy.stub(),
          addEventListener: cy.stub(),
          removeEventListener: cy.stub(),
          dispatchEvent: cy.stub(),
        }),
      })
    })
    cy.visit('/')
    cy.get('[data-animated]').should('have.css', 'animation', 'none')
  })

  it('should not have transition effects when reduced motion is preferred', () => {
    cy.window().then((win) => {
      Object.defineProperty(win, 'matchMedia', {
        writable: true,
        value: (query) => ({
          matches: query === '(prefers-reduced-motion: reduce)',
          media: query,
          onchange: null,
          addListener: cy.stub(),
          removeListener: cy.stub(),
          addEventListener: cy.stub(),
          removeEventListener: cy.stub(),
          dispatchEvent: cy.stub(),
        }),
      })
    })
    cy.reload()
    cy.get('[data-interactive]').should('have.css', 'transition', 'none')
  })

  it('should maintain normal animations when prefers-reduced-motion is not set', () => {
    cy.get('[data-animated]').should('not.have.css', 'animation', 'none')
  })

  it('should apply reduced motion styles to all animated elements', () => {
    cy.window().then((win) => {
      Object.defineProperty(win, 'matchMedia', {
        writable: true,
        value: (query) => ({
          matches: query === '(prefers-reduced-motion: reduce)',
          media: query,
          onchange: null,
          addListener: cy.stub(),
          removeListener: cy.stub(),
          addEventListener: cy.stub(),
          removeEventListener: cy.stub(),
          dispatchEvent: cy.stub(),
        }),
      })
    })
    cy.reload()
    cy.get('[class*="animate"]').each(($el) => {
      cy.wrap($el).should('have.css', 'animation', 'none')
    })
  })
})

