import { test, expect } from '@playwright/test';

test.describe('Responsive Image Scaling - Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await page.setViewportSize({ width: 375, height: 812 });
  });

  test('should scale images to fit screen width on mobile', async ({ page }) => {
    const images = await page.locator('img').all();
    const viewportSize = page.viewportSize();

    for (const img of images) {
      await expect(img).toBeVisible();
      const boundingBox = await img.boundingBox();
      expect(boundingBox.width).toBeLessThanOrEqual(viewportSize.width);
    }
  });

  test('should not have horizontal overflow on mobile viewport', async ({ page }) => {
    const bodyWidth = await page.evaluate(() => document.body.offsetWidth);
    const scrollWidth = await page.evaluate(() => document.body.scrollWidth);
    expect(scrollWidth).toBe(bodyWidth);
  });

  test('should maintain aspect ratio when scaling images', async ({ page }) => {
    const img = page.locator('img[data-testid="test-image"]').first();

    const naturalDimensions = await img.evaluate((element: HTMLImageElement) => ({
      width: element.naturalWidth,
      height: element.naturalHeight
    }));

    const displayDimensions = await img.boundingBox();

    const naturalRatio = naturalDimensions.width / naturalDimensions.height;
    const displayRatio = displayDimensions.width / displayDimensions.height;

    expect(Math.abs(displayRatio - naturalRatio)).toBeLessThan(0.01);
  });

  test('should display responsive images across different mobile viewports', async ({ page }) => {
    const viewports = [
      { width: 375, height: 667 },
      { width: 375, height: 812 },
      { width: 768, height: 1024 }
    ];

    for (const viewport of viewports) {
      await page.setViewportSize(viewport);
      const images = await page.locator('img').all();

      for (const img of images) {
        const maxWidth = await img.evaluate((el: HTMLElement) => 
          window.getComputedStyle(el).maxWidth
        );
        expect(maxWidth).toBe('100%');
      }
    }
  });
});

