describe('Sticky Footer Navigation on Mobile', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('iphone-x');
  });

  it('should display footer navigation on mobile viewport', () => {
    cy.get('footer nav').should('be.visible');
  });

  it('should have sticky positioning on mobile', () => {
    cy.get('footer nav').should('have.css', 'position', 'sticky');
  });

  it('should remain visible at bottom when scrolling down', () => {
    cy.get('body').then(($body) => {
      if ($body.height() > cy.viewport().height) {
        cy.scrollTo('bottom');
        cy.get('footer nav').should('be.visible');
        cy.get('footer nav').should('have.css', 'bottom', '0px');
      }
    });
  });

  it('should contain navigation links in footer', () => {
    cy.get('footer nav a').should('have.length.greaterThan', 0);
    cy.get('footer nav a').each(($link) => {
      cy.wrap($link).should('be.visible');
    });
  });

  it('should not overlap main content when scrolled', () => {
    cy.get('main').then(($main) => {
      const mainBottom = $main[0].getBoundingClientRect().bottom;
      cy.get('footer nav').then(($footer) => {
        const footerTop = $footer[0].getBoundingClientRect().top;
        expect(footerTop).to.be.greaterThan(mainBottom);
      });
    });
  });

  it('should be responsive on different mobile sizes', () => {
    const viewports = ['iphone-x', 'iphone-se2', 'samsung-s10'];
