describe('Pinch-to-zoom on product images', () => {
  beforeEach(() => {
    cy.visit('/product/test-product');
  });

  it('should zoom in on pinch gesture', () => {
    cy.get('[data-testid="product-image"]').should('be.visible');
    cy.get('[data-testid="product-image"]').trigger('touchstart', {
      touches: [{ clientX: 100, clientY: 100 }, { clientX: 200, clientY: 200 }]
    });
    cy.get('[data-testid="product-image"]').trigger('touchmove', {
      touches: [{ clientX: 80, clientY: 80 }, { clientX: 220, clientY: 220 }]
    });
    cy.get('[data-testid="product-image"]').should('have.css', 'transform').and('include', 'scale');
  });

  it('should zoom out on reverse pinch gesture', () => {
    cy.get('[data-testid="product-image"]').trigger('touchstart', {
      touches: [{ clientX: 80, clientY: 80 }, { clientY: 220, clientY: 220 }]
    });
    cy.get('[data-testid="product-image"]').trigger('touchmove', {
      touches: [{ clientX: 100, clientY: 100 }, { clientX: 200, clientY: 200 }]
    });
    cy.get('[data-testid="product-image"]').should('have.css', 'transform');
  });

  it('should maintain zoom level within acceptable bounds', () => {
    cy.get('[data-testid="product-image"]').then(($img) => {
      const initialScale = window.getComputedStyle($img[0]).transform;
      cy.get('[data-testid="product-image"]').trigger('touchstart', {
        touches: [{ clientX: 100, clientY: 100 }, { clientX: 200, clientY: 200 }]
      });
      cy.get('[data-testid="product-image"]').trigger('touchmove', {
        touches: [{ clientX: 50, clientY: 50 }, { clientX: 250, clientY: 250 }]
      });
      cy.get('[data-testid="product-image"]').should(($el) => {
        const transform = window.getComputedStyle($el[0]).transform;
        expect(transform).to.not.be.null;
      });
    });
  });

  it('should be functional on mobile viewport', () => {
    cy.viewport('iphone-x');
    cy.get('[data-testid="product-image"]').should('be.visible');
    cy.get('[data-testid="product-image"]').trigger('touchstart', {
      touches: [{ clientX: 100, clientY: 100 }, { clientX: 200, clientY: 200 }]
    });
    cy.get('[data-testid="product-image"]').trigger('touchmove', {
      touches: [{ clientX: 80, clientY: 80 }, { clientX: 220, clientY: 220 }]
    });
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Pinch-to-zoom on product images', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/product/test-product');
  });

  test('should zoom in on pinch gesture', async ({ page }) => {
    const image = page.locator('[data-testid="product-image"]');
    await expect(image).toBeVisible();
    const box = await image.boundingBox();
    await page.touchscreen.tap(box.x + box.width / 4, box.y + box.height / 4);
    await page.touchscreen.tap(box.x + (3 * box.width / 4), box.y + (3 * box.height / 4));
    const transform = await image.evaluate(el => window.getComputedStyle(el).transform);
    expect(transform).toBeTruthy();
  });

  test('should zoom out on reverse pinch gesture', async ({ page }) => {
    const image = page.locator('[data-testid="product-image"]');
    const box = await image.boundingBox();
    await page.touchscreen.tap(box.x + (box.width * 0.2), box.y + (box.height * 0.2));
    await page.touchscreen.tap(box.x + (box.width * 0.8), box.y + (box.height * 0.8));
    const transform = await image.evaluate(el => window.getComputedStyle(el).transform);
    expect(transform).toBeTruthy();
  });

  test('should maintain zoom level within acceptable bounds', async ({ page }) => {
    const image = page.locator('[data-testid="product-image"]');
    const box = await image.boundingBox();
    for (let i = 0; i < 3; i++) {
      await page.touchscreen.tap(box.x + box.width / 3, box.y + box.height / 3);
      await page.touchscreen.tap(box.x + (2 * box.width / 3), box.y + (2 * box.height / 3));
    }
    const transform = await image.evaluate(el => window.getComputedStyle(el).transform);
    expect(transform).not.toMatch(/scale\(\d{2,}/);
  });

  test('should be functional on mobile viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 812 });
    const image = page.locator('[data-testid="product-image"]');
    await expect(image).toBeVisible();
    const box = await image.boundingBox();
    await page.touchscreen.tap(box.x + box.width / 4, box.y + box.height / 4);
    await page.touchscreen.tap(box.x + (3 * box.width / 4), box.y + (3 * box.height / 4));
    const transform = await image.evaluate(el => window.getComputedStyle(el).transform);
    expect(transform).toBeTruthy();
  });

  test('should support double-tap zoom', async ({ page }) => {
    const image = page.locator('[data-testid="product-image"]');
    const box = await image.boundingBox();
    await page.touchscreen.tap(box.x + box.width / 2, box.y + box.height / 2);
    await page.waitForTimeout(50);
    await page.touchscreen.tap(box.x + box.width / 2, box.y + box.height / 2);
    const transform = await image.evaluate(el => window.getComputedStyle(el).transform);
    expect(transform).toBeTruthy();
  });
});

