describe('Search bar expand on focus - Mobile', () => {
  beforeEach(() => {
    cy.viewport('iphone-x');
    cy.visit('/');
  });

  it('should expand search bar on focus in mobile view', () => {
    cy.get('[data-testid="search-bar"]').should('be.visible');
    cy.get('[data-testid="search-bar"]').then(($searchBar) => {
      const initialWidth = $searchBar.width();
      cy.get('[data-testid="search-input"]').focus();
      cy.get('[data-testid="search-bar"]').then(($expandedBar) => {
        const expandedWidth = $expandedBar.width();
        expect(expandedWidth).to.be.greaterThan(initialWidth);
      });
    });
  });

  it('should collapse search bar on blur in mobile view', () => {
    cy.get('[data-testid="search-input"]').focus();
    cy.get('[data-testid="search-bar"]').then(($expandedBar) => {
      const expandedWidth = $expandedBar.width();
      cy.get('[data-testid="search-input"]').blur();
      cy.get('[data-testid="search-bar"]').then(($collapsedBar) => {
        const collapsedWidth = $collapsedBar.width();
        expect(collapsedWidth).to.be.lessThan(expandedWidth);
      });
    });
  });

  it('should not expand search bar on focus in desktop view', () => {
    cy.viewport(1280, 720);
    cy.get('[data-testid="search-bar"]').then(($searchBar) => {
      const initialWidth = $searchBar.width();
      cy.get('[data-testid="search-input"]').focus();
      cy.get('[data-testid="search-bar"]').then(($bar) => {
        const focusedWidth = $bar.width();
        expect(focusedWidth).to.equal(initialWidth);
      });
    });
  });

  it('should display search placeholder text when expanded', () => {
    cy.get('[data-testid="search-input"]').focus();
    cy.get('[data-testid="search-input"]').should('have.attr', 'placeholder');
  });

  it('should accept text input after expansion', () => {
    cy.get('[data-testid="search-input"]').focus();
    cy.get('[data-testid="search-input"]').type('test query');
    cy.get('[data-testid="search-input"]').should('have.value', 'test query');
  });
});

