describe('Mobile Landscape Orientation', () => {
  beforeEach(() => {
    cy.visit('/')
  })

  it('should display correctly in landscape orientation on mobile', () => {
    cy.viewport('iphone-x', 'landscape')
    cy.get('body').should('be.visible')
    cy.get('[data-testid="header"]').should('be.visible')
    cy.get('[data-testid="main-content"]').should('be.visible')
  })

  it('should not have horizontal scrollbar in landscape', () => {
    cy.viewport('iphone-x', 'landscape')
    cy.window().then(win => {
      expect(win.innerWidth).to.equal(win.document.documentElement.clientWidth)
    })
  })

  it('should maintain layout on various mobile devices in landscape', () => {
    const devices = ['iphone-x', 'iphone-8', 'samsung-s10']
    devices.forEach(device => {
      cy.viewport(device, 'landscape')
      cy.get('body').should('be.visible')
      cy.get('button').first().should('be.visible')
      cy.get('input').first().should('have.css', 'width').and('not.equal', '0px')
    })
  })

  it('should have readable text in landscape orientation', () => {
    cy.viewport('iphone-x', 'landscape')
    cy.get('body').should('have.css', 'font-size').and('not.equal', '0px')
    cy.get('p, span, h1, h2, h3').each(el => {
      cy.wrap(el).should('have.css', 'font-size').and('not.equal', '0px')
    })
  })

  it('should have properly aligned navigation in landscape', () => {
    cy.viewport('iphone-x', 'landscape')
    cy.get('[data-testid="nav"]').should('be.visible')
    cy.get('[data-testid="nav"] a').each(link => {
      cy.wrap(link).should('be.visible')
    })
  })
})

