import { test, expect } from '@playwright/test';

test.describe('Mobile Landscape Orientation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/')
  })

  test('should display correctly in landscape orientation on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 812, height: 375 })
    const header = await page.locator('[data-testid="header"]')
    await expect(header).toBeVisible()
    const mainContent = await page.locator('[data-testid="main-content"]')
    await expect(mainContent).toBeVisible()
  })

  test('should not have horizontal scrollbar in landscape', async ({ page }) => {
    await page.setViewportSize({ width: 812, height: 375 })
    const scrollWidth = await page.evaluate(() => document.documentElement.scrollWidth)
    const clientWidth = await page.evaluate(() => document.documentElement.clientWidth)
    expect(scrollWidth).toBeLessThanOrEqual(clientWidth)
  })

  test('should maintain layout on various mobile devices in landscape', async ({ page }) => {
    const devices = [
      { width: 812, height: 375 },
      { width: 667, height: 375 },
      { width: 960, height: 540 }
    ]
    for (const viewport of devices) {
      await page.setViewportSize(viewport)
      const body = await page.locator('body')
      await expect(body).toBeVisible()
      const button = await page.locator('button').first()
      await expect(button).toBeVisible()
    }
  })

  test('should have readable text in landscape orientation', async ({ page }) => {
    await page.setViewportSize({ width: 812, height: 375 })
    const elements = await page.locator('p, span, h1, h2, h3')
    const count = await elements.count()
    for (let i = 0; i < count; i++) {
      const fontSize = await elements.nth(i).evaluate(el => window.getComputedStyle(el).fontSize)
      expect(fontSize).not.toBe('0px')
    }
  })

  test('should have properly aligned navigation in landscape', async ({ page }) => {
    await page.setViewportSize({ width: 812, height: 375 })
    const nav = await page.locator('[data-testid="nav"]')
    await expect(nav).toBeVisible()
    const navLinks = await page.locator('[data-testid="nav"] a')
    const linkCount = await navLinks.count()
    for (let i = 0; i < linkCount; i++) {
      await expect(navLinks.nth(i)).toBeVisible()
    }
  })
})
